DG.put("krisnaavtaar/22",{"n":22,"title":"ਅਥ ਲੁਕ ਮੀਚਨ ਖੇਲ ਕਥਨੰ","title_roman":"Ath luk meechan khel kathnan","page":367,"blocks":[{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":367,"meaning_status":"draft"},{"type":"verse","number":[228],"number_text":"੨੨੮।","page":367,"lines":[{"gurmukhi":"ਮਾਰਿ ਪ੍ਰਲੰਬ ਲਯੋ ਮੁਸਲੀ ਜਬ ਯਾਦ ਕਰੀ ਹਰਿ ਜੀ ਤਬ ਗਾਈ।","roman":"Maari pralanb layo muslee jab yaad karee hari jee tab gaaee |","meaning_en":"When Balram had killed Pralamb, then Hari remembered the cows.","page":367,"meaning_status":"draft","note":"ਮੁਸਲੀ: Balram."},{"gurmukhi":"ਚੂਮਨ ਲਾਗ ਤਬੈ ਬਛਰਾ ਮੁਖ ਧੇਨ ਵਹੈ ਉਨ ਕੀ ਅਰੁ ਮਾਈ।","roman":"Chooman laag tabai bachhraa mukh dhen vahai un kee aru maaee |","meaning_en":"Then the calves began to kiss the faces of the cows, their mothers.","page":367,"meaning_status":"draft"},{"gurmukhi":"ਹੋਇ ਪ੍ਰਸੰਨ੍ਯ ਤਬੈ ਕਰੁਨਾਨਿਧ ਤਉ ਲੁਕ ਮੀਚਨ ਖੇਲ ਮਚਾਈ।","roman":"Hoi prasanny tabai karunaanidh tau luk meechan khel machaaee |","meaning_en":"Then the treasure of mercy, pleased, started a game of hide-and-seek.","page":367,"meaning_status":"draft","note":"ਲੁਕ ਮੀਚਨ: a game of hiding and eye-covering."},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਕੇ ਮਨ ਮੈ ਬਹੁ ਭਾਤਿਨ ਭਾਈ। ੨੨੮।","roman":"Taa chhabi kee ati hee upmaa kabi ke man mai bahu bhaatin bhaaee | 228 |","meaning_en":"Many comparisons for that lovely sight pleased the poet's mind.","page":367,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":367,"meaning_status":"draft"},{"type":"verse","number":[229],"number_text":"੨੨੯।","page":367,"lines":[{"gurmukhi":"ਬੈਠਿ ਕਰਿ ਗ੍ਵਾਰ ਆਖੈ ਮੀਚੈ ਏਕ ਗ੍ਵਾਰ ਹੂੰ ਕੀ","roman":"Baithi kari gvaar aakhai meechai ek gvaar hoon kee","meaning_en":"Sitting down, one cowherd covers the eyes of another cowherd,","page":367,"meaning_status":"draft"},{"gurmukhi":"ਛੋਰਿ ਦੇਤ ਤਾ ਕੋ ਸੋ ਤੋ ਅਉਰੋ ਗਹੈ ਧਾਇ ਕੈ।","roman":"Chhori det taa ko so to auro gahai dhaai kai |","meaning_en":"then lets him go, and he runs and catches someone else.","page":367,"meaning_status":"draft"},{"gurmukhi":"ਆਖੈ ਮੂੰਦਤ ਹੈ ਤਬ ਓਹੀ ਗੋਪ ਹੂੰ ਕੀ ਫੇਰਿ","roman":"Aakhai moondat hai tab ohee gop hoon kee pheri","meaning_en":"Then the eyes of that same cowherd are covered in turn,","page":367,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੇ ਤਨ ਕੋ ਜੋ ਛੁਐ ਕਰ ਸਾਥ ਜਾਇ ਕੈ।","roman":"Jaa ke tan ko jo chhuai kar saath jaai kai |","meaning_en":"whoever's body he goes and touches with his hand.","page":367,"meaning_status":"draft"},{"gurmukhi":"ਤਹ ਤੋ ਛਲ ਬਲ ਕੈ ਪਲਾਵੈ ਹਾਥਿ ਆਵੈ ਨਹੀ","roman":"Tah to chhal bal kai palaavai haathi aavai nahee","meaning_en":"There, by trick and strength, they run off and do not come into his hands;","page":367,"meaning_status":"draft"},{"gurmukhi":"ਤਉ ਮਿਟਾਵੈ ਆਖੈ ਆਪ ਹੀ ਤੇ ਸੋ ਤੋ ਆਇ ਕੈ।","roman":"Tau mitaavai aakhai aap hee te so to aai kai |","meaning_en":"then he comes and uncovers his eyes himself.","page":367,"meaning_status":"draft"},{"gurmukhi":"ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਤਾ ਕੀ ਮਹਿਮਾ ਨ ਲਖੀ ਜਾਇ","roman":"Kahai kabi syaam taa kee mahimaa na lakhee jaai","meaning_en":"Says the poet Shyam: his glory cannot be perceived;","page":367,"meaning_status":"draft"},{"gurmukhi":"ਐਸੀ ਭਾਤਿ ਖੇਲੈ ਕਾਨ੍ਹ ਮਹਾ ਸੁਖੁ ਪਾਇ ਕੈ।੨੨੯।","roman":"Aisee bhaati khelai kaanh mahaa sukhu paai kai | 229 |","meaning_en":"in this way Kanh plays, finding great joy.","page":367,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":367,"meaning_status":"draft"},{"type":"verse","number":[230],"number_text":"੨੩੦।","page":367,"lines":[{"gurmukhi":"ਅੰਤ ਭਏ ਰੁਤਿ ਗ੍ਰੀਖਮ ਕੀ ਰੁਤਿ ਪਾਵਸ ਆਇ ਗਈ ਸੁਖਦਾਈ।","roman":"Ant bhae ruti greekham kee ruti paavas aai gaee sukhdaaee |","meaning_en":"The hot season ended and the pleasant rainy season came.","page":367,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨ੍ਹ ਫਿਰੈ ਬਨ ਬੀਥਿਨ ਮੈ ਸੰਗਿ ਲੈ ਬਛਰੇ ਤਿਨ ਕੀ ਅਰੁ ਮਾਈ।","roman":"Kaanh phirai ban beethin mai sangi lai bachhre tin kee aru maaee |","meaning_en":"Kanh roams the forest paths, taking with him the calves and their mothers.","page":367,"meaning_status":"draft"},{"gurmukhi":"ਬੈਠਿ ਤਬੈ ਫਿਰਿ ਮਧ ਗੁਫਾ ਗਿਰਿ ਗਾਵਤ ਗੀਤ ਸਭੈ ਮਨੁ ਭਾਈ।","roman":"Baithi tabai phiri madh guphaa giri gaavat geet sabhai manu bhaaee |","meaning_en":"Then, sitting inside a mountain cave, they all sang songs that pleased the heart.","page":367,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਨੇ ਮੁਖ ਤੇ ਇਮ ਭਾਖਿ ਸੁਨਾਈ। ੨੩੦।","roman":"Taa chhabi kee ati hee upmaa kabi ne mukh te im bhaakhi sunaaee | 230 |","meaning_en":"The poet spoke and told the great beauty of that sight thus:","page":367,"meaning_status":"draft"}]},{"type":"verse","number":[231],"number_text":"੨੩੧।","page":367,"lines":[{"gurmukhi":"ਸੋਰਠਿ ਸਾਰੰਗ ਅਉ ਗੁਜਰੀ ਲਲਤਾ ਅਰੁ ਭੈਰਵ ਦੀਪਕ ਗਾਵੈ।","roman":"Sorthi saarang au gujree laltaa aru bhairav deepak gaavai |","meaning_en":"He sings Sorath, Sarang and Gujri, Lalita, Bhairav and Dipak;","page":367,"meaning_status":"draft","note":"Names of ragas."},{"gurmukhi":"ਟੋਡੀ ਅਉ ਮੇਘ ਮਲ੍ਹਾਰ ਅਲਾਪਤ ਗੌਡ ਅਉ ਸੁਧ ਮਲ੍ਹਾਰ ਸੁਨਾਵੈ।","roman":"Todee au megh malhaar alaapat gaud au sudh malhaar sunaavai |","meaning_en":"he sings out Todi and Megh Malhar, and lets Gaund and Shuddh Malhar be heard;","page":367,"meaning_status":"draft"},{"gurmukhi":"ਜੈਤਸਰੀ ਅਰੁ ਮਾਲਸਿਰੀ ਅਉ ਪਰਜ ਸੁ ਰਾਗਸਿਰੀ ਠਟ ਪਾਵੈ।","roman":"Jaitasree aru maalsiree au paraj su raagsiree that paavai |","meaning_en":"he sets forth Jaitsari and Malsiri, and Paraj and Siri Rag.","page":367,"meaning_status":"draft","note":"ਠਟ ਪਾਵੈ: read as 'sets forth, arranges'."},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਹਰਿ ਜੀ ਰਿਝ ਕੈ ਮੁਰਲੀ ਸੰਗ ਕੋਟਕ ਰਾਗ ਬਜਾਵੈ। ੨੩੧।","roman":"Syaam kahai hari jee rijh kai murlee sang kotak raag bajaavai | 231 |","meaning_en":"Says Shyam: Hari, delighted, plays countless ragas on the flute.","page":367,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":368,"meaning_status":"draft"},{"type":"verse","number":[232],"number_text":"੨੩੨।","page":368,"lines":[{"gurmukhi":"ਲਲਤ ਧਨਾਸਰੀ ਬਜਾਵਹਿ ਸੰਗਿ ਬਾਸੁਰੀ ਕਿਦਾਰਾ ਔਰ ਮਾਲਵਾ ਬਿਹਾਗੜਾ ਅਉ ਗੂਜਰੀ।","roman":"Lalat dhanaasree bajaavhi sangi baasuree kidaaraa aur maalvaa bihaagraa au goojree |","meaning_en":"On the flute he plays Lalit, Dhanasari, Kedara, and Malva, Bihagara and Gujri;","page":368,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰੂ ਅਉ ਪਰਜ ਔਰ ਕਾਨੜਾ ਕਲਿਆਨ ਸੁਭ ਕੁਕਭ ਬਿਲਾਵਲੁ ਸੁਨੈ ਤੇ ਆਵੈ ਮੂਜਰੀ।","roman":"Maaroo au paraj aur kaanraa kaliaan subh kukabh bilaavlu sunai te aavai moojree |","meaning_en":"Maru and Paraj and Kanara, auspicious Kalyan, Kakubh and Bilaval; on hearing them people come to pay homage.","page":368,"meaning_status":"draft","note":"ਮੂਜਰੀ: read as 'homage, salutation' (mujra); uncertain."},{"gurmukhi":"ਭੈਰਵ ਪਲਾਸੀ ਭੀਮ ਦੀਪਕ ਸੁ ਗਉਰੀ ਨਟ ਠਾਢੋ ਦ੍ਰੁਮ ਛਾਇ ਮੈ ਸੁ ਗਾਵੈ ਕਾਨ੍ਹ ਪੂਜਰੀ।","roman":"Bhairav palaasee bheem deepak su gauree nat thaadho drum chhaai mai su gaavai kaanh poojree |","meaning_en":"Bhairav, Palasi, Bhim, Dipak, Gauri and Nat: standing in the shade of a tree, worshipful Kanh sings them.","page":368,"meaning_status":"draft","note":"ਪੂਜਰੀ: read as 'worshipful'; uncertain."},{"gurmukhi":"ਤਾਤੇ ਗ੍ਰਿਹ ਤਿਆਗਿ ਤਾ ਕੀ ਸੁਨਿ ਧੁਨਿ ਸ੍ਰੋਨਨ ਮੈ ਮ੍ਰਿਗਨੈਨੀ ਫਿਰਤ ਸੁ ਬਨਿ ਬਨਿਊਜਰੀ।੨੩੨।","roman":"Taate grih tiaagi taa kee suni dhuni sronan mai mrignainee phirat su bani banioojree | 232 |","meaning_en":"Hearing that sound in their ears, the doe-eyed women leave their homes and wander, distracted, from forest to forest.","page":368,"meaning_status":"draft","note":"ਬਨਿਊਜਰੀ: read as 'in the forests, distraught'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":368,"meaning_status":"draft"},{"type":"verse","number":[233],"number_text":"੨੩੩।","page":368,"lines":[{"gurmukhi":"ਸੀਤ ਭਈ ਰੁਤਿ ਕਾਤਿਕ ਕੀ ਮੁਨਿ ਦੇਵ ਚੜਿਓ ਜਲ ਹ੍ਵੈ ਗਯੋ ਥੋਰੋ।","roman":"Seet bhaee ruti kaatik kee muni dev chario jal hvai gayo thoro |","meaning_en":"The cold season of Kartik came; the sage's star rose and the water became low.","page":368,"meaning_status":"draft","note":"ਮੁਨਿ ਦੇਵ ਚੜਿਓ: read as the rising of the star of the sage Agastya, said to make waters subside; uncertain."},{"gurmukhi":"ਕਾਨ੍ਹ ਕਨੀਰੇ ਕੇ ਫੂਲ ਧਰੇ ਅਰੁ ਗਾਵਤ ਬੇਨ ਬਜਾਵਤ ਭੋਰੋ।","roman":"Kaanh kaneere ke phool dhare aru gaavat ben bajaavat bhoro |","meaning_en":"Kanh wears oleander flowers, and at dawn sings and plays the flute.","page":368,"meaning_status":"draft","note":"ਕਨੀਰੇ: oleander (kaner)."},{"gurmukhi":"ਸ੍ਯਾਮ ਕਿਧੋ ਉਪਮਾ ਤਿਹ ਕੀ ਮਨ ਮਧਿ ਬਿਚਾਰੁ ਕਬਿਤੁ ਸੁ ਜੋਰੋ।","roman":"Syaam kidho upmaa tih kee man madhi bichaaru kabitu su joro |","meaning_en":"Shyam, thinking in his mind of a comparison for it, composed this verse:","page":368,"meaning_status":"draft"},{"gurmukhi":"ਮੈਨ ਉਠਿਯੋ ਜਗਿ ਕੈ ਤਿਨ ਕੈ ਤਨਿ ਲੇਤ ਹੈ ਪੇਚ ਮਨੋ ਅਹਿ ਤੋਰੋ। ੨੩੩।","roman":"Main uthiyo jagi kai tin kai tani let hai pech mano ahi toro | 233 |","meaning_en":"Love has woken and risen in their bodies, writhing as though it were a wounded snake.","page":368,"meaning_status":"draft","note":"ਮੈਨ: Love, Kamadev. ਅਹਿ ਤੋਰੋ: read as 'a broken (injured) snake'; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"The gopis said:","page":368,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":368,"meaning_status":"draft"},{"type":"verse","number":[234],"number_text":"੨੩੪।","page":368,"lines":[{"gurmukhi":"ਬੋਲਤ ਹੈ ਮੁਖ ਤੇ ਸਭ ਗਵਾਰਿਨ ਪੁੰਨਿ ਕਰਿਓ ਇਨ ਹੂੰ ਅਤਿ ਮਾਈ।","roman":"Bolat hai mukh te sabh gavaarin punni kario in hoon ati maaee |","meaning_en":"All the cowherd women say from their mouths, 'O mother, this flute has done great merit.","page":368,"meaning_status":"draft","note":"The subject 'flute' is understood from the context."},{"gurmukhi":"ਜਗ੍ਯ ਕਰਿਯੋ ਕਿ ਕਰਿਯੋ ਤਪ ਤੀਰਥ ਗੰਧ੍ਰਬ ਤੇ ਇਨ ਕੈ ਸਿਛ ਪਾਈ।","roman":"Jagy kariyo ki kariyo tap teerath gandhrab te in kai sichh paaee |","meaning_en":"Did it perform sacrifices, or austerities, or pilgrimages? Did it receive teaching from the Gandharvas?","page":368,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਕਿ ਪੜੀ ਸਿਤਬਾਨਹੁ ਤੇ ਕਿ ਕਿਧੋ ਚਤੁਰਾਨਨਿ ਆਪ ਬਨਾਈ।","roman":"Kai ki paree sitbaanhu te ki kidho chaturaanni aap banaaee |","meaning_en":"Or did it learn from the white-clad goddess, or did four-faced Brahma make it himself?'","page":368,"meaning_status":"draft","note":"ਸਿਤਬਾਨਹੁ: read as Saraswati, 'the one in white'; uncertain."},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਉਪਮਾ ਤਿਹ ਕੀ ਇਹ ਤੇ ਹਰਿ ਓਠਨ ਸਾਥ ਲਗਾਈ। ੨੩੪।","roman":"Syaam kahai upmaa tih kee ih te hari othan saath lagaaee | 234 |","meaning_en":"Says Shyam, its glory is this, that for this reason Hari has put it to his lips.","page":368,"meaning_status":"draft"}]},{"type":"verse","number":[235],"number_text":"੨੩੫।","page":368,"lines":[{"gurmukhi":"ਸੁਤ ਨੰਦ ਬਜਾਵਤ ਹੈ ਮੁਰਲੀ ਉਪਮਾ ਤਿਹ ਕੀ ਕਬਿ ਸ੍ਯਾਮ ਗਨੋ।","roman":"Sut nand bajaavat hai murlee upmaa tih kee kabi syaam gano |","meaning_en":"Nand's son plays the flute; the poet Shyam reckons up a comparison for it.","page":368,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਕੀ ਧੁਨਿ ਕੋ ਸੁਨਿ ਮੋਹ ਰਹੇ ਮੁਨਿ ਰੀਝਤ ਹੈ ਸੁ ਜਨੋ ਰੁ ਕਨੋ।","roman":"Tih kee dhuni ko suni moh rahe muni reejhat hai su jano ru kano |","meaning_en":"Hearing its sound the sages are spellbound, and delighted in every particle of their being.","page":368,"meaning_status":"draft","note":"ਸੁ ਜਨੋ ਰੁ ਕਨੋ: sense uncertain; read as 'through and through'."},{"gurmukhi":"ਤਨ ਕਾਮ ਭਰੀ ਗੁਪੀਆ ਸਭ ਹੀ ਮੁਖ ਤੇ ਇਹ ਭਾਤਨ ਜਵਾਬ ਭਨੋ।","roman":"Tan kaam bharee gupeeaa sabh hee mukh te ih bhaatan javaab bhano |","meaning_en":"The gopis, their bodies full of desire, all give this answer from their mouths:","page":368,"meaning_status":"draft"},{"gurmukhi":"ਮੁਖ ਕਾਨ੍ਹ ਗੁਲਾਬ ਕੋ ਫੂਲ ਭਯੋ ਇਹ ਨਾਲਿ ਗੁਲਾਬ ਚੁਆਤ ਮਨੋ। ੨੩੫।","roman":"Mukh kaanh gulaab ko phool bhayo ih naali gulaab chuaat mano | 235 |","meaning_en":"'Kanh's face has become a rose, and this flute is like a pipe dripping rose-water.'","page":368,"meaning_status":"draft","note":"ਨਾਲਿ: read as 'pipe, tube'."}]},{"type":"verse","number":[236],"number_text":"੨੩੬।","page":368,"lines":[{"gurmukhi":"ਮੋਹਿ ਰਹੇ ਸੁਨਿ ਕੈ ਧੁਨਿ ਕੌ ਮ੍ਰਿਗ ਮੋਹਿ ਪਸਾਰ ਗੇ ਖਗ ਪੈ ਪਖਾ।","roman":"Mohi rahe suni kai dhuni kau mrig mohi pasaar ge khag pai pakhaa |","meaning_en":"Hearing the sound, the deer are spellbound, and the birds, spellbound, have spread their wings.","page":368,"meaning_status":"draft"},{"gurmukhi":"ਨੀਰ ਬਹਿਓ ਜਮੁਨਾ ਉਲਟੋ ਪਿਖਿ ਕੈ ਤਿਹ ਕੋ ਨਰ ਖੋਲ ਰੇ ਚਖਾ।","roman":"Neer bahio jamunaa ulto pikhi kai tih ko nar khol re chakhaa |","meaning_en":"The water of the Yamuna flowed backwards; seeing it, people opened their eyes wide.","page":368,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਤਿਨ ਕੋ ਸੁਨਿ ਕੈ ਬਛੁਰਾ ਮੁਖ ਸੋ ਕਛੁ ਨ ਚੁਗੈ ਕਖਾ।","roman":"Syaam kahai tin ko suni kai bachhuraa mukh so kachhu na chugai kakhaa |","meaning_en":"Says Shyam, hearing it, the calves do not pick a single blade of grass with their mouths.","page":368,"meaning_status":"draft"},{"gurmukhi":"ਛੋਡਿ ਚਲੀ ਪਤਨੀ ਅਪਨੇ ਪਤਿ ਤਾਰਕ ਹ੍ਵੈ ਜਿਮ ਡਾਰਤ ਲਖਾ। ੨੩੬।","roman":"Chhodi chalee patnee apne pati taarak hvai jim daarat lakhaa | 236 |","meaning_en":"Wives went off leaving their own husbands, as a renunciant casts away wealth by the lakh.","page":368,"meaning_status":"draft","note":"ਤਾਰਕ ਹ੍ਵੈ ਜਿਮ ਡਾਰਤ ਲਖਾ: read as 'like one who renounces throwing away lakhs'; uncertain."}]},{"type":"verse","number":[237],"number_text":"੨੩੭।","page":368,"lines":[{"gurmukhi":"ਕੋਕਿਲ ਕੀਰ ਕੁਰੰਗਨ ਕੇਹਰਿ ਮੈਨ ਰਹਿਯੋ ਹ੍ਵੈ ਕੈ ਮਤਵਾਰੋ।","roman":"Kokil keer kurangan kehri main rahiyo hvai kai matvaaro |","meaning_en":"The cuckoo, the parrot, the deer, the lion, and Love himself have become intoxicated.","page":368,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝ ਰਹੇ ਸਭ ਹੀ ਪੁਰ ਕੇ ਜਨ ਆਨਨ ਪੈ ਇਹ ਤੈ ਸਸਿ ਹਾਰੋ।","roman":"Reejh rahe sabh hee pur ke jan aanan pai ih tai sasi haaro |","meaning_en":"All the people of the town are enchanted; before his face the moon is defeated.","page":368,"meaning_status":"draft"},{"gurmukhi":"ਅਉ ਇਹ ਕੀ ਮੁਰਲੀ ਜੁ ਬਜੈ ਤਿਹ ਊਪਰਿ ਰਾਗ ਸਭੈ ਫੁਨਿ ਵਾਰੋ।","roman":"Au ih kee murlee ju bajai tih oopri raag sabhai phuni vaaro |","meaning_en":"And when his flute plays, all the ragas are offered up as a sacrifice to it.","page":369,"meaning_status":"draft"},{"gurmukhi":"ਨਾਰਦ ਜਾਤ ਥਕੈ ਇਹ ਤੈ ਬੰਸੁਰੀ ਜੁ ਬਜਾਵਤ ਕਾਨਰ ਕਾਰੋ। ੨੩੭।","roman":"Naarad jaat thakai ih tai bansuree ju bajaavat kaanar kaaro | 237 |","meaning_en":"Even Narad grows weary before this, when dark Kanh plays the flute.","page":369,"meaning_status":"draft","note":"ਨਾਰਦ ਜਾਤ ਥਕੈ: read as 'Narad is outdone'; uncertain."}]},{"type":"verse","number":[238],"number_text":"੨੩੮।","page":369,"lines":[{"gurmukhi":"ਲੋਚਨ ਹੈ ਮ੍ਰਿਗ ਕੇ ਕਟਿ ਕੇਹਰਿ ਨਾਕ ਕਿਧੋ ਸੁਕ ਸੋ ਤਿਹ ਕੋ ਹੈ।","roman":"Lochan hai mrig ke kati kehri naak kidho suk so tih ko hai |","meaning_en":"His eyes are a deer's, his waist a lion's, and his nose like a parrot's;","page":369,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਰੀਵ ਕਪੋਤ ਸੀ ਹੈ ਤਿਹ ਕੀ ਅਧਰਾ ਪੀਆ ਸੇ ਹਰਿ ਮੂਰਤਿ ਜੋ ਹੈ।","roman":"Greev kapot see hai tih kee adhraa peeaa se hari moorti jo hai |","meaning_en":"his neck is like a dove's, and his lips like nectar, he who is the very form of Hari.","page":369,"meaning_status":"draft","note":"ਪੀਆ ਸੇ: read as 'like nectar' (piyush); uncertain."},{"gurmukhi":"ਕੋਕਿਲ ਅਉ ਪਿਕ ਸੇ ਬਚਨਾਮ੍ਰਿਤ ਸ੍ਯਾਮ ਕਹੈ ਕਬਿ ਸੁੰਦਰ ਸੋਹੈ।","roman":"Kokil au pik se bachnaamrit syaam kahai kabi sundar sohai |","meaning_en":"His nectar-sweet words are like the koel and the cuckoo; says the poet Shyam, he looks beautiful.","page":369,"meaning_status":"draft"},{"gurmukhi":"ਪੈ ਇਹ ਤੇ ਲਜ ਕੈ ਅਬ ਬੋਲਤ ਮੂਰਤਿ ਲੈਨ ਕਰੈ ਖਗ ਰੋਹੈ। ੨੩੮।","roman":"Pai ih te laj kai ab bolat moorti lain karai khag rohai | 238 |","meaning_en":"But, shamed by him, the birds now sing only in vexation.","page":369,"meaning_status":"draft","note":"ਬੋਲਤ ਮੂਰਤਿ ਲੈਨ ਕਰੈ ਖਗ ਰੋਹੈ: sense unclear; read as the birds being put to shame and angered; uncertain."}]},{"type":"verse","number":[239],"number_text":"੨੩੯।","page":369,"lines":[{"gurmukhi":"ਫੂਲ ਗੁਲਾਬ ਨ ਲੇਤ ਹੈ ਤਾਬ ਸਹਾਬ ਕੋ ਆਬ ਹ੍ਵੈ ਦੇਖਿ ਖਿਸਾਨੋ।","roman":"Phool gulaab na let hai taab sahaab ko aab hvai dekhi khisaano |","meaning_en":"The rose cannot bear comparison; the lustre of the ruby is abashed on seeing him.","page":369,"meaning_status":"draft","note":"Persian words: ਤਾਬ 'endurance/glow', ਸਹਾਬ read as a red gem or flame (shihab), ਆਬ 'lustre', ਖਿਸਾਨੋ 'ashamed'; uncertain."},{"gurmukhi":"ਪੈ ਕਮਲਾ ਦਲ ਨਰਗਸ ਕੋ ਗੁਲ ਲਜਤ ਹ੍ਵੈ ਫੁਨਿ ਦੇਖਤ ਤਾਨੋ।","roman":"Pai kamlaa dal nargas ko gul lajat hvai phuni dekhat taano |","meaning_en":"And the lotus petal and the narcissus flower are ashamed when they look on him.","page":369,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਕਿਧੋ ਅਪੁਨੇ ਮਨ ਮੈ ਬਰਤਾ ਗਨਿ ਕੈ ਕਬਿਤਾ ਇਹ ਠਾਨੋ।","roman":"Syaam kidho apune man mai bartaa gani kai kabitaa ih thaano |","meaning_en":"Shyam, weighing it in his own mind, composed this poem:","page":369,"meaning_status":"draft","note":"ਬਰਤਾ: read as 'comparison'; uncertain."},{"gurmukhi":"ਦੇਖਨ ਕੋ ਇਨ ਕੇ ਸਮ ਪੂਰਬ ਪਛਮ ਡੋਲੈ ਲਹੈ ਨਹਿ ਆਨੋ। ੨੩੯।","roman":"Dekhan ko in ke sam poorab pachham dolai lahai nahi aano | 239 |","meaning_en":"to see one equal to him, one may roam east and west and find no other.","page":369,"meaning_status":"draft"}]},{"type":"verse","number":[240],"number_text":"੨੪੦।","page":369,"lines":[{"gurmukhi":"ਮੰਘਰ ਮੈ ਸਭ ਹੀ ਗੁਪੀਆ ਮਿਲਿ ਪੂਜਤ ਚੰਡਿ ਪਤੇ ਹਰਿ ਕਾਜੈ।","roman":"Manghar mai sabh hee gupeeaa mili poojat chandi pate hari kaajai |","meaning_en":"In the month of Maghar all the gopis together worship Chandi to have Hari as their husband.","page":369,"meaning_status":"draft","note":"ਚੰਡਿ ਪਤੇ ਹਰਿ ਕਾਜੈ: read as 'worship Chandi for the sake of Hari as husband'."},{"gurmukhi":"ਪ੍ਰਾਤ ਸਮੇ ਜਮੁਨਾ ਮਧਿ ਨ੍ਹਾਵਤ ਦੇਖਿ ਤਿਨੈ ਜਲਜੰ ਮੁਖ ਲਾਜੈ।","roman":"Praat same jamunaa madhi nhaavat dekhi tinai jaljan mukh laajai |","meaning_en":"They bathe in the Yamuna at dawn; seeing them, the lotus is shamed.","page":369,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਗੀਤ ਬਿਲਾਵਲ ਮੈ ਜੁਰਿ ਬਾਹਨਿ ਸ੍ਯਾਮ ਕਥਾ ਇਹ ਸਾਜੈ।","roman":"Gaavat geet bilaaval mai juri baahni syaam kathaa ih saajai |","meaning_en":"Joined arm in arm, they sing songs in Bilaval; so Shyam composes this tale.","page":369,"meaning_status":"draft","note":"ਜੁਰਿ ਬਾਹਨਿ: read as 'arm in arm'; uncertain."},{"gurmukhi":"ਅੰਗਿ ਅਨੰਗ ਬਢਿਓ ਤਿਨ ਕੇ ਪਿਖ ਕੈ ਜਿਹ ਲਾਜ ਕੋ ਭਾਜਨ ਭਾਜੈ।੨੪੦।","roman":"Angi anang badhio tin ke pikh kai jih laaj ko bhaajan bhaajai | 240 |","meaning_en":"Love grew in their limbs; seeing it, even the very vessel of modesty runs away.","page":369,"meaning_status":"draft","note":"ਜਿਹ ਲਾਜ ਕੋ ਭਾਜਨ ਭਾਜੈ: sense uncertain."}]},{"type":"verse","number":[241],"number_text":"੨੪੧।","page":369,"lines":[{"gurmukhi":"ਗਾਵਤ ਗੀਤ ਬਿਲਾਵਲ ਮੈ ਸਭ ਹੀ ਮਿਲਿ ਗੋਪਿਨ ਉਜਲ ਕਾਰੀ।","roman":"Gaavat geet bilaaval mai sabh hee mili gopin ujal kaaree |","meaning_en":"All the gopis, fair and dark, sing songs together in Bilaval.","page":369,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨਰ ਕੋ ਭਰਤਾ ਕਰਬੇ ਕਹੁ ਬਾਛਤ ਹੈ ਪਤਲੀ ਅਰੁ ਭਾਰੀ।","roman":"Kaanar ko bhartaa karbe kahu baachhat hai patlee aru bhaaree |","meaning_en":"Slender and plump alike, they long to make Kanh their husband.","page":369,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਕਰੈ ਤਿਨ ਕੇ ਮੁਖ ਕੌ ਪਿਖਿ ਜੋਤਿ ਕਲਾ ਸਸਿ ਕੀ ਫੁਨਿ ਹਾਰੀ।","roman":"Syaam karai tin ke mukh kau pikhi joti kalaa sasi kee phuni haaree |","meaning_en":"Says Shyam: seeing their faces, the brilliance of the moon's phases was defeated.","page":369,"meaning_status":"draft","note":"ਕਰੈ: printed so; read as 'says' (kahai)."},{"gurmukhi":"ਨ੍ਹਾਵਤ ਹੈ ਜਮੁਨਾ ਜਲ ਮੈ ਜਨੁ ਫੂਲ ਰਹੀ ਗ੍ਰਿਹ ਮੈ ਫੁਲਵਾਰੀ। ੨੪੧।","roman":"Nhaavat hai jamunaa jal mai janu phool rahee grih mai phulvaaree | 241 |","meaning_en":"They bathe in the Yamuna's water, as though a garden were blooming within a house.","page":369,"meaning_status":"draft"}]},{"type":"verse","number":[242],"number_text":"੨੪੨।","page":369,"lines":[{"gurmukhi":"ਨ੍ਹਾਵਤ ਹੈ ਗੁਪੀਆ ਜਲ ਮੈ ਤਿਨ ਕੇ ਮਨ ਮੈ ਫੁਨਿ ਹਉਲ ਨ ਕੋ।","roman":"Nhaavat hai gupeeaa jal mai tin ke man mai phuni haul na ko |","meaning_en":"The gopis bathe in the water, and there is no fear at all in their minds.","page":369,"meaning_status":"draft"},{"gurmukhi":"ਗੁਨ ਗਾਵਤ ਤਾਲ ਬਜਾਵਤ ਹੈ ਤਿਹ ਜਾਇ ਕਿਧੌ ਇਕ ਠਉਲਨ ਕੋ।","roman":"Gun gaavat taal bajaavat hai tih jaai kidhau ik thaulan ko |","meaning_en":"They sing his praises and clap the time; they go there as if for play.","page":369,"meaning_status":"draft","note":"ਠਉਲਨ: read as 'play, frolic'."},{"gurmukhi":"ਮੁਖਿ ਤੇ ਉਚਰੈ ਇਹ ਭਾਤਿ ਸਭੈ ਇਤਨੋ ਸੁਖ ਨ ਹਰਿ ਧਉਲਨ ਕੋ।","roman":"Mukhi te uchrai ih bhaati sabhai itno sukh na hari dhaulan ko |","meaning_en":"They all say from their mouths: 'Not even Hari's white palaces hold so much joy.'","page":369,"meaning_status":"draft","note":"ਹਰਿ ਧਉਲਨ: read as 'the white mansions of Hari (or of the gods)'; uncertain."},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਬਿਰਾਜਤ ਹੈ ਅਤਿ ਸਹੀ ਇਕ ਬਨਿਓ ਸਰ ਸੁੰਦਰ ਕਉਲਨ ਕੋ।੨੪੨।","roman":"Kabi syaam biraajat hai ati sahee ik banio sar sundar kaulan ko | 242 |","meaning_en":"Says the poet Shyam, they look very lovely, as if a beautiful lake of lotuses had formed.","page":369,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","roman":"Gopee baach devee joo so","meaning_en":"The gopis said to the goddess:","page":369,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":369,"meaning_status":"draft"},{"type":"verse","number":[243],"number_text":"੨੪੩।","page":369,"lines":[{"gurmukhi":"ਲੈ ਅਪੁਨੇ ਕਰ ਜੋ ਮਿਟੀਆ ਤਿਹ ਥਾਪ ਕਹੈ ਮੁਖ ਤੇ ਜੁ ਭਵਾਨੀ।","roman":"Lai apune kar jo miteeaa tih thaap kahai mukh te ju bhavaanee |","meaning_en":"Taking clay in their hands, they shape her image and say from their mouths, 'Bhavani.'","page":369,"meaning_status":"draft"},{"gurmukhi":"ਪਾਇ ਪਰੈ ਤਿਹ ਕੇ ਹਿਤ ਸੋ ਕਰਿ ਕੋਟਿ ਪ੍ਰਨਾਮੁ ਕਹੈ ਇਹ ਬਾਨੀ।","roman":"Paai parai tih ke hit so kari koti pranaamu kahai ih baanee |","meaning_en":"With love they fall at her feet and, making countless salutations, speak these words:","page":369,"meaning_status":"draft"},{"gurmukhi":"ਪੂਜਤ ਹੈ ਇਹ ਤੇ ਹਮ ਤੋ ਤੁਮ ਦੇਹੁ ਵਹੈ ਜੀਅ ਮੈ ਹਮ ਠਾਨੀ।","roman":"Poojat hai ih te ham to tum dehu vahai jeea mai ham thaanee |","meaning_en":"'We worship you for this: grant us what we have resolved in our hearts.","page":370,"meaning_status":"draft"},{"gurmukhi":"ਹ੍ਵੈ ਹਮਰੋ ਭਰਤਾ ਹਰਿ ਜੀ ਮੁਖਿ ਸੁੰਦਰਿ ਹੈ ਜਿਹ ਕੋ ਸਸਿ ਸਾਨੀ। ੨੪੩।","roman":"Hvai hamro bhartaa hari jee mukhi sundri hai jih ko sasi saanee | 243 |","meaning_en":"May Hari become our husband, whose face is as beautiful as the moon.'","page":370,"meaning_status":"draft"}]},{"type":"verse","number":[244],"number_text":"੨੪੪।","page":370,"lines":[{"gurmukhi":"ਭਾਲਿ ਲਗਾਵਤ ਕੇਸਰ ਅਛਤ ਚੰਦਨ ਲਾਵਤ ਹੈ ਸਿਤ ਕੈ।","roman":"Bhaali lagaavat kesar achhat chandan laavat hai sit kai |","meaning_en":"On her forehead they put saffron and rice grains, and apply white sandal paste.","page":370,"meaning_status":"draft","note":"ਸਿਤ ਕੈ: read as 'white'; could be 'with heart' (chit); uncertain."},{"gurmukhi":"ਫੁਨਿ ਡਾਰਤ ਫੂਲ ਉਡਾਵਤ ਹੈ ਮਖੀਆ ਤਿਹ ਕੀ ਅਤਿ ਹੀ ਹਿਤ ਕੈ।","roman":"Phuni daarat phool udaavat hai makheeaa tih kee ati hee hit kai |","meaning_en":"Then they scatter flowers, and with great love wave a fly-whisk over her.","page":370,"meaning_status":"draft"},{"gurmukhi":"ਪਟ ਧੂਪ ਪਚਾਮ੍ਰਿਤ ਦਛਨਾ ਪਾਨ ਪ੍ਰਦਛਨਾ ਦੇਤ ਮਹਾ ਚਿਤ ਕੈ।","roman":"Pat dhoop pachaamrit dachhnaa paan pradachhnaa det mahaa chit kai |","meaning_en":"With great devotion they offer cloth, incense, panchamrit, gifts and betel, and walk around her.","page":370,"meaning_status":"draft"},{"gurmukhi":"ਬਰਬੇ ਕਹੁ ਕਾਨ੍ਹ ਉਪਾਉ ਕਰੈ ਮਿਤ ਹੋ ਸੋਊ ਤਾਤ ਕਿਧੌ ਕਿਤ ਕੈ। ੨੪੪।","roman":"Barbe kahu kaanh upaau karai mit ho so'oo taat kidhau kit kai | 244 |","meaning_en":"They try every means to wed Kanh: 'Let him be our beloved, whoever his father may be.'","page":370,"meaning_status":"draft","note":"ਮਿਤ ਹੋ ਸੋਊ ਤਾਤ ਕਿਧੌ ਕਿਤ ਕੈ: sense very uncertain."}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","roman":"Gopee baach devee joo so","meaning_en":"The gopis said to the goddess:","page":370,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":370,"meaning_status":"draft"},{"type":"verse","number":[245],"number_text":"੨੪੫।","page":370,"lines":[{"gurmukhi":"ਦੈਤਨ ਸੰਘਾਰਨੀ ਪਤਿਤ ਲੋਕ ਤਾਰਨੀ ਸੁ ਸੰਕਟ ਨਿਵਾਰਨੀ ਕਿ ਐਸੀ ਤੂੰ ਸਕਤਿ ਹੈ।","roman":"Daitan sanghaarnee patit lok taarnee su sankat nivaarnee ki aisee toon sakti hai |","meaning_en":"'Destroyer of demons, saviour of fallen people, remover of troubles: such a power you are.","page":370,"meaning_status":"draft"},{"gurmukhi":"ਬੇਦਨ ਉਧਾਰਨੀ ਸੁਰੇਂਦ੍ਰ ਰਾਜ ਕਾਰਨੀ ਪੈ ਗਉਰਜਾ ਕੀ ਜਾਗੈ ਜੋਤਿ ਅਉਰ ਜਾਨ ਕਤ ਹੈ।","roman":"Bedan udhaarnee surendr raaj kaarnee pai gaurjaa kee jaagai joti aur jaan kat hai |","meaning_en":"Rescuer of the Vedas, giver of kingship to Indra; it is the light of Gauri that shines, and where else is it known?","page":370,"meaning_status":"draft","note":"ਗਉਰਜਾ: Gauri, Parvati; line sense uncertain."},{"gurmukhi":"ਧੂਅ ਮੈ ਨ ਧਰਾ ਮੈ ਨ ਧਿਆਨ ਧਾਰੀ ਮੈ ਪੈ ਕਛੂ ਜੈਸੇ ਤੇਰੇ ਜੋਤਿ ਬੀਚ ਆਨਨ ਛਕਤਿ ਹੈ।","roman":"Dhooa mai na dharaa mai na dhiaan dhaaree mai pai kachhoo jaise tere joti beech aanan chhakti hai |","meaning_en":"Not in the sky, not in the earth, not in the meditator is there anything like what is absorbed in your light.","page":370,"meaning_status":"draft","note":"ਧੂਅ: read as 'sky' or the pole star (Dhruv); ਆਨਨ ਛਕਤਿ: uncertain."},{"gurmukhi":"ਦਿਨਸ ਦਿਨੇਸ ਮੈ ਦਿਵਾਨ ਮੈ ਸੁਰੇਸ ਮੈ ਸੁਪਤ ਮਹੇਸ ਜੋਤਿ ਤੇਰੀ ਐ ਜਗਤਿ ਹੈ। ੨੪੫।","roman":"Dinas dines mai divaan mai sures mai supat mahes joti teree ai jagti hai | 245 |","meaning_en":"In the day, in the sun, in the lamp, in Indra, and in sleeping Mahesh, it is your light that is awake.'","page":370,"meaning_status":"draft","note":"ਦਿਵਾਨ: read as 'lamp'; uncertain. Mahesh: Shiva."}]},{"type":"verse","number":[246],"number_text":"੨੪੬।","page":370,"lines":[{"gurmukhi":"ਬਿਨਤੀ ਕਰਤ ਸਭ ਗੋਪੀ ਕਰਿ ਜੋਰਿ ਜੋਰਿ ਸੁਨਿ ਲੇਹੁ ਬਿਨਤੀ ਹਮਾਰੀ ਇਹ ਚੰਡਿਕਾ।","roman":"Bintee karat sabh gopee kari jori jori suni lehu bintee hamaaree ih chandikaa |","meaning_en":"All the gopis pray, folding their hands again and again: 'Hear this prayer of ours, O Chandika.","page":370,"meaning_status":"draft"},{"gurmukhi":"ਸੁਰ ਤੈ ਉਬਾਰੇ ਕੋਟਿ ਪਤਿਤ ਉਧਾਰੇ ਚੰਡ ਮੁੰਡ ਮੁੰਡ ਡਾਰੇ ਸੁੰਭ ਨਿਸੁੰਭ ਕੀ ਖੰਡਿਕਾ।","roman":"Sur tai ubaare koti patit udhaare chand mund mund daare sunbh nisunbh kee khandikaa |","meaning_en":"You saved the gods, rescued millions of the fallen, cut off the heads of Chand and Mund, and are the destroyer of Sumbh and Nisumbh.","page":370,"meaning_status":"draft"},{"gurmukhi":"ਦੀਜੈ ਮਾਗਿਯੋ ਦਾਨ ਹ੍ਵੈ ਪ੍ਰਤਛ ਕਹੈ ਮੇਰੀ ਮਾਈ ਪੂਜੇ ਹਮ ਤੁਮੈ ਨਾਹੀ ਪੁਜੈ ਸੁਤ ਗੰਡਕਾ।","roman":"Deejai maagiyo daan hvai pratachh kahai meree maaee pooje ham tumai naahee pujai sut gandkaa |","meaning_en":"Appear before us and grant the gift we ask, O our mother; we worship you, not the son of the Gandaki.'","page":370,"meaning_status":"draft","note":"ਸੁਤ ਗੰਡਕਾ: read as the saligram stone from the Gandaki river; uncertain."},{"gurmukhi":"ਹ੍ਵੈ ਕਰਿ ਪ੍ਰਸੰਨ੍ਯ ਤਾ ਕੋ ਕਹਿਓ ਸੀਘ੍ਰ ਮਾਨ ਦੀਨੋ ਵਹੈ ਬਰ ਦਾਨ ਫੁਨਿ ਰਾਨਿਨ ਕੀਮੰਡਿਕਾ।੨੪੬।","roman":"Hvai kari prasanny taa ko kahio seeghr maan deeno vahai bar daan phuni raanin keemandikaa | 246 |","meaning_en":"Pleased, she told them, 'Accept it quickly'; and she, the ornament of queens, then gave that very boon.","page":370,"meaning_status":"draft","note":"ਰਾਨਿਨ ਕੀ ਮੰਡਿਕਾ: read as 'adornment of queens'; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਦੇਵੀ ਜੀ ਬਾਚ ਗੋਪਿਨ ਸੋ","gurmukhi":"ਦੇਵੀ ਜੀ ਬਾਚ ਗੋਪਿਨ ਸੋ","roman":"Devee jee baach gopin so","meaning_en":"The goddess said to the gopis:","page":370,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":370,"meaning_status":"draft"},{"type":"verse","number":[247],"number_text":"੨੪੭।","page":370,"lines":[{"gurmukhi":"ਹ੍ਵੈ ਭਰਤਾ ਅਬ ਸੋ ਤੁਮਰੋ ਹਰਿ ਦਾਨ ਇਹੇ ਦੁਰਗਾ ਤਿਨ ਦੀਨਾ।","roman":"Hvai bhartaa ab so tumro hari daan ihe durgaa tin deenaa |","meaning_en":"'Hari will now be your husband': this gift Durga gave them.","page":370,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਧੁਨਿ ਸ੍ਰਉਨਨ ਮੈ ਸੁਨ ਕੈ ਤਿਨ ਕੋਟਿ ਪ੍ਰਨਾਮ ਤਬੈ ਉਠਿ ਕੀਨਾ।","roman":"So dhuni sraunan mai sun kai tin koti pranaam tabai uthi keenaa |","meaning_en":"Hearing those words with their ears, they rose and made countless salutations.","page":370,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਛਬਿ ਕੋ ਜਸੁ ਉਚ ਮਹਾ ਕਬਿ ਨੇ ਅਪਨੇ ਮਨ ਮੈ ਫੁਨਿ ਚੀਨਾ।","roman":"Taa chhabi ko jasu uch mahaa kabi ne apne man mai phuni cheenaa |","meaning_en":"Then the poet perceived in his mind the high and great glory of that sight:","page":370,"meaning_status":"draft"},{"gurmukhi":"ਹੈ ਇਨ ਕੋ ਮਨੁ ਕਾਨਰ ਮੈ ਅਉ ਜੋ ਪੈ ਰਸ ਕਾਨਰ ਕੇ ਸੰਗਿ ਭੀਨਾ। ੨੪੭।","roman":"Hai in ko manu kaanar mai au jo pai ras kaanar ke sangi bheenaa | 247 |","meaning_en":"their minds are set on Kanh, and they are steeped in love with Kanh.","page":370,"meaning_status":"draft"}]},{"type":"verse","number":[248],"number_text":"੨੪੮।","page":371,"lines":[{"gurmukhi":"ਪਾਇ ਪਰੀ ਤਿਹ ਕੇ ਤਬ ਹੀ ਸਭ ਭਾਤਿ ਕਰੀ ਬਹੁ ਤਾਹਿ ਬਡਾਈ।","roman":"Paai paree tih ke tab hee sabh bhaati karee bahu taahi badaaee |","meaning_en":"Then they fell at her feet and praised her greatly in every way:","page":371,"meaning_status":"draft"},{"gurmukhi":"ਹੈ ਜਗ ਕੀ ਕਰਤਾ ਹਰਤਾ ਦੁਖ ਹੈ ਸਭ ਤੂ ਗਨ ਗੰਧ੍ਰਬ ਮਾਈ।","roman":"Hai jag kee kartaa hartaa dukh hai sabh too gan gandhrab maaee |","meaning_en":"'You are the creator of the world and the remover of sorrow; you are the mother of all ganas and gandharvas.'","page":371,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਨੇ ਮੁਖ ਤੇ ਇਮ ਭਾਖਿ ਸੁਨਾਈ।","roman":"Taa chhabi kee ati hee upmaa kabi ne mukh te im bhaakhi sunaaee |","meaning_en":"The poet spoke and told of that sight thus:","page":371,"meaning_status":"draft"},{"gurmukhi":"ਲਾਲ ਭਈ ਤਬ ਹੀ ਗੁਪੀਆ ਫੁਨਿ ਬਾਤ ਜਬੈ ਮਨ ਬਾਛਤ ਪਾਈ। ੨੪੮।","roman":"Laal bhaee tab hee gupeeaa phuni baat jabai man baachhat paaee | 248 |","meaning_en":"the gopis glowed red with joy when they obtained what their hearts desired.","page":371,"meaning_status":"draft"}]},{"type":"verse","number":[249],"number_text":"੨੪੯।","page":371,"lines":[{"gurmukhi":"ਲੈ ਬਰਦਾਨ ਸਭੈ ਗੁਪੀਆ ਅਤਿ ਆਨੰਦ ਕੈ ਮਨਿ ਡੇਰਨ ਆਈ।","roman":"Lai bardaan sabhai gupeeaa ati aanand kai mani deran aaee |","meaning_en":"Having received the boon, all the gopis came home with great joy in their hearts.","page":371,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਗੀਤ ਸਭੈ ਮਿਲ ਕੈ ਇਕ ਹ੍ਵੈ ਕੈ ਪ੍ਰਸੰਨ੍ਯ ਸੁ ਦੇਤ ਬਧਾਈ।","roman":"Gaavat geet sabhai mil kai ik hvai kai prasanny su det badhaaee |","meaning_en":"They all sing songs together and, united and happy, congratulate one another.","page":371,"meaning_status":"draft"},{"gurmukhi":"ਪਾਤਨ ਸਾਥ ਖਰੀ ਤਿਨ ਕੀ ਉਪਮਾ ਕਬਿ ਨੇ ਮੁਖ ਤੇ ਇਮ ਗਾਈ।","roman":"Paatan saath kharee tin kee upmaa kabi ne mukh te im gaaee |","meaning_en":"Of them standing together in rows, the poet sang this comparison:","page":371,"meaning_status":"draft","note":"ਪਾਤਨ ਸਾਥ ਖਰੀ: read as 'standing in rows'; uncertain."},{"gurmukhi":"ਮਾਨਹੁ ਪਾਇ ਨਿਸਾਪਤਿ ਕੋ ਸਰ ਮਧਿ ਖਿਰੀ ਕਵੀਆ ਧੁਰ ਤਾਈ। ੨੪੯।","roman":"Maanhu paai nisaapti ko sar madhi khiree kaveeaa dhur taaee | 249 |","meaning_en":"as if, on seeing the moon, the night-lilies in the lake had bloomed fully.","page":371,"meaning_status":"draft","note":"ਕਵੀਆ: read as night-blooming lilies (kumudini); ਧੁਰ ਤਾਈ: 'fully'; uncertain."}]},{"type":"verse","number":[250],"number_text":"੨੫੦।","page":371,"lines":[{"gurmukhi":"ਪ੍ਰਾਤ ਭਏ ਜਮਨਾ ਜਲ ਮੈ ਮਿਲਿ ਧਾਇ ਗਈ ਸਭ ਹੀ ਗੁਪੀਆ।","roman":"Praat bhae jamnaa jal mai mili dhaai gaee sabh hee gupeeaa |","meaning_en":"At dawn all the gopis together hurried to the waters of the Yamuna.","page":371,"meaning_status":"draft"},{"gurmukhi":"ਮਿਲਿ ਗਾਵਤ ਗੀਤ ਚਲੀ ਤਿਹ ਜਾ ਕਰਿ ਆਨੰਦ ਭਾਮਿਨ ਮੈ ਕੁਪੀਆ।","roman":"Mili gaavat geet chalee tih jaa kari aanand bhaamin mai kupeeaa |","meaning_en":"Together they went there singing songs, the women brimming with joy.","page":371,"meaning_status":"draft","note":"ਕੁਪੀਆ: read as 'brimming like flasks'; uncertain."},{"gurmukhi":"ਤਬ ਹੀ ਫੁਨਿ ਕਾਨ੍ਹ ਚਲੇ ਤਿਹ ਜਾ ਜਮੁਨਾ ਜਲ ਕੋ ਫੁਨਿ ਜਾ ਜੁ ਪੀਆ।","roman":"Tab hee phuni kaanh chale tih jaa jamunaa jal ko phuni jaa ju peeaa |","meaning_en":"Just then Kanh also went to that place, the beloved, to the Yamuna's water.","page":371,"meaning_status":"draft","note":"ਜਾ ਜੁ ਪੀਆ: sense uncertain; may also mean 'where they drink'."},{"gurmukhi":"ਸੋਊ ਦੇਖਿ ਤਬੈ ਭਗਵਾਨ ਕਹੇ ਨਹਿ ਬੋਲਹੁ ਰੀ ਕਰਿ ਹੋ ਚੁਪੀਆ। ੨੫੦।","roman":"So'oo dekhi tabai bhagvaan kahe nahi bolhu ree kari ho chupeeaa | 250 |","meaning_en":"Seeing them, the Lord then said, 'Don't speak, keep quiet.'","page":371,"meaning_status":"draft","note":"Who is told to keep quiet is unclear; uncertain."}]},{"type":"heading","kind":"section_heading","name":"ਅਥ ਚੀਰ ਚਰਨ ਕਥਨੰ","gurmukhi":"ਅਥ ਚੀਰ ਚਰਨ ਕਥਨੰ","roman":"Ath cheer charan kathnan","meaning_en":"Now begins the account of the taking of the clothes.","page":371,"meaning_status":"draft","note":"ਚੀਰ ਚਰਨ: printed so; read as 'clothes-stealing' (chir haran)."},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":371,"meaning_status":"draft"},{"type":"verse","number":[251],"number_text":"੨੫੧।","page":371,"lines":[{"gurmukhi":"ਨ੍ਹਾਵਨਿ ਲਾਗਿ ਜਬੈ ਗੁਪੀਆ ਤਬ ਲੈ ਪਟ ਕਾਨ ਚਰਿਯੋ ਤਰੁ ਊਪੈ।","roman":"Nhaavni laagi jabai gupeeaa tab lai pat kaan chariyo taru oopai |","meaning_en":"When the gopis began to bathe, Kanh took their clothes and climbed up a tree.","page":371,"meaning_status":"draft"},{"gurmukhi":"ਤਉ ਮੁਸਕਯਾਨ ਲਗੀ ਮਧਿ ਆਪਨ ਕੋਇ ਪੁਕਾਰ ਕਰੇ ਹਰਿ ਜੂ ਪੈ।","roman":"Tau musakyaan lagee madhi aapan koi pukaar kare hari joo pai |","meaning_en":"Then they began to smile among themselves, and some called out to Hari:","page":371,"meaning_status":"draft"},{"gurmukhi":"ਚੀਰ ਹਰੇ ਹਮਰੇ ਛਲ ਸੋ ਤੁਮ ਸੋ ਠਗ ਨਾਹਿ ਕਿਧੋ ਕੋਊ ਭੂ ਪੈ।","roman":"Cheer hare hamre chhal so tum so thag naahi kidho ko'oo bhoo pai |","meaning_en":"'You have stolen our clothes by a trick; there is no cheat like you on earth.","page":371,"meaning_status":"draft"},{"gurmukhi":"ਹਾਥਨ ਸਾਥ ਸੁ ਸਾਰੀ ਹਰੀ ਦ੍ਰਿਗ ਸਾਥ ਹਰੋ ਹਮਰੋ ਤੁਮ ਰੂਪੈ। ੨੫੧।","roman":"Haathan saath su saaree haree drig saath haro hamro tum roopai | 251 |","meaning_en":"With your hands you have taken our saris, and with your eyes you have stolen our beauty.'","page":371,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ ਜੂ ਸੋ","roman":"Gopee baach kaan joo so","meaning_en":"The gopis said to Kanh:","page":371,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":371,"meaning_status":"draft"},{"type":"verse","number":[252],"number_text":"੨੫੨।","page":371,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਕਹਿਯੋ ਮੁਖ ਤੇ ਗੁਪੀਆ ਇਹ ਕਾਨ੍ਹ ਸਿਖੇ ਤੁਮ ਬਾਤ ਭਲੀ ਹੈ।","roman":"Syaam kahiyo mukh te gupeeaa ih kaanh sikhe tum baat bhalee hai |","meaning_en":"Says Shyam: the gopis said from their mouths, 'Kanh, this is a fine thing you have learned!","page":371,"meaning_status":"draft"},{"gurmukhi":"ਨੰਦ ਕੀ ਓਰ ਪਿਖੋ ਤੁਮ ਹੂੰ ਦਿਖੋ ਭ੍ਰਾਤ ਕੀ ਓਰ ਕਿ ਨਾਮ ਹਲੀ ਹੈ।","roman":"Nand kee or pikho tum hoon dikho bhraat kee or ki naam halee hai |","meaning_en":"Look towards Nand, and look towards your brother, whose name is Balram.","page":371,"meaning_status":"draft","note":"ਹਲੀ: Balram."},{"gurmukhi":"ਚੀਰ ਹਰੇ ਹਮਰੇ ਛਲ ਸੋ ਸੁਨਿ ਮਾਰਿ ਡਰੈ ਤੁਹਿ ਕੰਸ ਬਲੀ ਹੈ।","roman":"Cheer hare hamre chhal so suni maari darai tuhi kans balee hai |","meaning_en":"You stole our clothes by a trick; if mighty Kans hears of it he will kill you.","page":371,"meaning_status":"draft"},{"gurmukhi":"ਕੋ ਮਰ ਹੈ ਹਮ ਕੋ ਤੁਮਰੋ ਨ੍ਰਿਪ ਤੋਰ ਡਰੈ ਜਿਮ ਕਉਲ ਕਲੀ ਹੈ। ੨੫੨।","roman":"Ko mar hai ham ko tumro nrip tor darai jim kaul kalee hai | 252 |","meaning_en":"Who will kill us? The king will break you as one breaks a lotus bud.'","page":371,"meaning_status":"draft","note":"First half sense uncertain."}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ ਗੋਪੀ ਸੋ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ ਗੋਪੀ ਸੋ","roman":"Kaanh baach gopee so","meaning_en":"Kanh said to the gopis:","page":372,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":372,"meaning_status":"draft"},{"type":"verse","number":[253],"number_text":"੨੫੩।","page":372,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਤਿਨ ਕੋ ਇਹ ਬਾਤ ਨ ਦਿਓ ਪਟ ਹਉ ਨਿਕਰਿਯੋ ਬਿਨੁ ਤੋ ਕੋ।","roman":"Kaanh kahee tin ko ih baat na dio pat hau nikriyo binu to ko |","meaning_en":"Kanh said this to them: 'I will not give the clothes unless you come out.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਕਿਉ ਜਲ ਬੀਚ ਰਹੀ ਛਪ ਕੈ ਤਨ ਕਾਹਿ ਕਟਾਵਤ ਹੋ ਪਹਿ ਜੋਕੋ।","roman":"Kiu jal beech rahee chhap kai tan kaahi kataavat ho pahi joko |","meaning_en":"Why do you stay hidden in the water? Why do you let the leeches bite your bodies?","page":372,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਬਤਾਵਤ ਹੋ ਨ੍ਰਿਪ ਕੋ ਤਿਹ ਕੋ ਫੁਨਿ ਨਾਹਿ ਕਛੂ ਡਰੁ ਮੋਕੋ।","roman":"Naam bataavat ho nrip ko tih ko phuni naahi kachhoo daru moko |","meaning_en":"You speak the king's name, but I have no fear of him at all.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਕੇਸਨ ਤੇ ਗਹਿ ਕੈ ਤਪ ਕੀ ਅਗਨੀ ਮਧਿ ਈਧਨ ਜਿਉ ਉਹਿ ਝੋਕੋ। ੨੫੩।","roman":"Kesan te gahi kai tap kee agnee madhi eedhan jiu uhi jhoko | 253 |","meaning_en":"I would seize him by the hair and throw him like firewood into the blazing fire.'","page":372,"meaning_status":"draft","note":"ਤਪ ਕੀ ਅਗਨੀ: read as 'burning fire'."}]},{"type":"verse","number":[254],"number_text":"੨੫੪।","page":372,"lines":[{"gurmukhi":"ਰੂਖਿ ਚਰੇ ਹਰਿ ਜੀ ਰਿਝ ਕੈ ਮੁਖ ਤੇ ਜਬ ਬਾਤ ਕਹੀ ਇਹ ਤਾ ਸੋ।","roman":"Rookhi chare hari jee rijh kai mukh te jab baat kahee ih taa so |","meaning_en":"When Hari, sitting delighted in the tree, said this to them,","page":372,"meaning_status":"draft","note":"ਰੂਖਿ ਚਰੇ: 'climbed on the tree'."},{"gurmukhi":"ਤਉ ਰਿਸਿ ਬਾਤ ਕਹੀ ਉਨ ਹੂੰ ਇਹ ਜਾਇ ਕਹੈ ਤੁਹਿ ਮਾਤ ਪਿਤਾ ਸੋ।","roman":"Tau risi baat kahee un hoon ih jaai kahai tuhi maat pitaa so |","meaning_en":"then they said this in anger: 'We will go and tell your mother and father.'","page":372,"meaning_status":"draft"},{"gurmukhi":"ਜਾਇ ਕਹੋ ਇਹ ਕਾਨ੍ਹ ਕਹੀ ਮਨ ਹੈ ਤੁਮਰੋ ਕਹਬੇ ਕਹੁ ਜਾ ਸੋ।","roman":"Jaai kaho ih kaanh kahee man hai tumro kahbe kahu jaa so |","meaning_en":"Kanh said, 'Go and tell it to whomever you have a mind to tell.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਸੁਨਿ ਕੋਊ ਕਹੈ ਹਮ ਕੋ ਇਹ ਤੋ ਹਮ ਹੂੰ ਸਮਝੈ ਫੁਨਿ ਵਾ ਸੋ। ੨੫੪।","roman":"Jo suni ko'oo kahai ham ko ih to ham hoon samjhai phuni vaa so | 254 |","meaning_en":"If anyone hears it and says anything to me, then I will deal with him.'","page":372,"meaning_status":"draft","note":"ਸਮਝੈ ... ਵਾ ਸੋ: read as 'settle with him'; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"Kanh said:","page":372,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":372,"meaning_status":"draft"},{"type":"verse","number":[255],"number_text":"੨੫੫।","page":372,"lines":[{"gurmukhi":"ਦੇਉ ਬਿਨਾ ਨਿਕਰੈ ਨਹਿ ਚੀਰ ਕਹਿਯੋ ਹਸਿ ਕਾਨ੍ਹ ਸੁਨੋ ਤੁਮ ਪਿਆਰੀ।","roman":"Deu binaa nikrai nahi cheer kahiyo hasi kaanh suno tum piaaree |","meaning_en":"'I will not give the clothes unless you come out,' said Kanh, laughing. 'Listen, my dears.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਸੀਤ ਸਹੋ ਜਲ ਮੈ ਤੁਮ ਨਾਹਕ ਬਾਹਰਿ ਆਵਹੋ ਗੋਰੀ ਅਉ ਕਾਰੀ।","roman":"Seet saho jal mai tum naahak baahri aavho goree au kaaree |","meaning_en":"You suffer the cold in the water for nothing; come out, fair ones and dark ones.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਦੇ ਅਪੁਨੇ ਅਗੂਆ ਪਿਛੂਆ ਕਰ ਬਾਰਿ ਤਜੋ ਪਤਲੀ ਅਰੁ ਭਾਰੀ।","roman":"De apune agooaa pichhooaa kar baari tajo patlee aru bhaaree |","meaning_en":"Putting your hands before and behind you, leave the water, slender and plump alike.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਨਹਿ ਦੇਉ ਕਹਿਓ ਹਰਿ ਜੀ ਤਸਲੀਮ ਕਰੋ ਕਰ ਜੋਰਿ ਹਮਾਰੀ। ੨੫੫।","roman":"Yau nahi deu kahio hari jee tasleem karo kar jori hamaaree | 255 |","meaning_en":"I will not give them like this,' said Hari, 'salute me with joined hands.'","page":372,"meaning_status":"draft","note":"ਤਸਲੀਮ: Persian, 'salutation'."}]},{"type":"verse","number":[256],"number_text":"੨੫੬।","page":372,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਹਰਿ ਜੀ ਤਿਨ ਸੋ ਰਿਝ ਕੈ ਇਹ ਬਾਤ ਸੁਨੋ ਤੁਮ ਮੇਰੀ।","roman":"Pheri kahee hari jee tin so rijh kai ih baat suno tum meree |","meaning_en":"Again Hari, delighted, said to them, 'Listen to this word of mine.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਹਮਰੋ ਕਰ ਲਾਜ ਕੀ ਕਾਟਿ ਸਭੈ ਤੁਮ ਬੇਰੀ।","roman":"Jori pranaam karo hamro kar laaj kee kaati sabhai tum beree |","meaning_en":"Join your hands and bow to me, cutting away all your fetters of shame.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਬਾਰ ਹੀ ਬਾਰ ਕਹਿਯੋ ਤੁਮ ਸੋ ਮੁਹਿ ਮਾਨਹੁ ਸੀਘ੍ਰ ਕਿਧੋ ਇਹ ਹੇ ਰੀ।","roman":"Baar hee baar kahiyo tum so muhi maanhu seeghr kidho ih he ree |","meaning_en":"Again and again I have told you; obey me quickly, girls.","page":372,"meaning_status":"draft"},{"gurmukhi":"ਨਾਤੁਰ ਜਾਇ ਕਹੋ ਸਭ ਹੀ ਪਹਿ ਸਉਹ ਲਗੈ ਫੁਨਿ ਠਾਕੁਰ ਕੇਰੀ। ੨੫੬।","roman":"Naatur jaai kaho sabh hee pahi sauh lagai phuni thaakur keree | 256 |","meaning_en":"Otherwise I will go and tell everyone, I swear by the Lord.'","page":372,"meaning_status":"draft","note":"ਕਹੋ: who is to tell is unclear; could be 'you go and tell'; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","roman":"Gopee baach kaanh so","meaning_en":"The gopis said to Kanh:","page":372,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":372,"meaning_status":"draft"},{"type":"verse","number":[257],"number_text":"੨੫੭।","page":372,"lines":[{"gurmukhi":"ਜੋ ਤੁਮ ਜਾਇ ਕਹੋ ਤਿਨ ਹੀ ਪਹਿ ਤੋ ਹਮ ਬਾਤ ਬਨਾਵਹਿ ਐਸੇ।","roman":"Jo tum jaai kaho tin hee pahi to ham baat banaavhi aise |","meaning_en":"'If you go and tell them, then we will make up a story like this:","page":372,"meaning_status":"draft"},{"gurmukhi":"ਚੀਰ ਹਰੇ ਹਮਰੇ ਹਰਿ ਜੀ ਦਈ ਬਾਰਿ ਤੇ ਨਿਆਰੀ ਕਢੈ ਹਮ ਕੈਸੇ।","roman":"Cheer hare hamre hari jee daee baari te niaaree kadhai ham kaise |","meaning_en":"\"Hari stole our clothes; O God, how could we come out of the water?\"","page":372,"meaning_status":"draft","note":"ਦਈ ... ਨਿਆਰੀ: read as 'O God ... out'; uncertain."},{"gurmukhi":"ਭੇਦ ਕਹੈ ਸਭ ਹੀ ਜਸੁਧਾ ਪਹਿ ਤੋਹਿ ਕਰੈ ਸਰਮਿੰਦਤ ਵੈਸੇ।","roman":"Bhed kahai sabh hee jasudhaa pahi tohi karai sarmindat vaise |","meaning_en":"We will tell the whole secret to Yashoda and put you to shame, just","page":372,"meaning_status":"draft"},{"gurmukhi":"ਜਿਉ ਨਰ ਕੋ ਗਹਿ ਕੈ ਤਿਰੀਯਾ ਹੂੰ ਸੁ ਮਾਰਤ ਲਾਤਨ ਮੂਕਨ ਜੈਸੇ। ੨੫੭।","roman":"Jiu nar ko gahi kai tireeyaa hoon su maarat laatan mookan jaise | 257 |","meaning_en":"as when women seize a man and beat him with kicks and fists.'","page":372,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"Kanh said:","page":373,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":373,"meaning_status":"draft"},{"type":"verse","number":[258],"number_text":"੨੫੮।","page":373,"lines":[{"gurmukhi":"ਬਾਤ ਕਹੀ ਤਬ ਇਹ ਹਰੀ ਕਾਹਿ ਬੰਧਾਵਤ ਮੋਹਿ।","roman":"Baat kahee tab ih haree kaahi bandhaavat mohi |","meaning_en":"Then Hari said this: 'Why would you have me tied up?","page":373,"meaning_status":"draft","note":"ਬੰਧਾਵਤ: 'have me bound' (as by Yashoda); uncertain."},{"gurmukhi":"ਨਮਸਕਾਰ ਜੋ ਨ ਕਰੋ ਮੋਹਿ ਦੁਹਾਈ ਤੋਹਿ। ੨੫੮।","roman":"Namaskaar jo na karo mohi duhaaee tohi | 258 |","meaning_en":"If you do not bow to me, I solemnly charge you by my oath.'","page":373,"meaning_status":"draft","note":"ਮੋਹਿ ਦੁਹਾਈ ਤੋਹਿ: sense uncertain."}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"The gopis said:","page":373,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":373,"meaning_status":"draft"},{"type":"verse","number":[259],"number_text":"੨੫੯।","page":373,"lines":[{"gurmukhi":"ਕਾਹਿ ਖਿਝਾਵਤ ਹੋ ਹਮ ਕੋ ਅਰੁ ਦੇਤ ਕਹਾ ਜਦੁਰਾਇ ਦੁਹਾਈ।","roman":"Kaahi khijhaavat ho ham ko aru det kahaa jaduraai duhaaee |","meaning_en":"'Why do you tease us, and why do you swear oaths, O king of the Yadavs?","page":373,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਬਿਧਿ ਕਾਰਨ ਬਾਤ ਬਨਾਵਤ ਸੋ ਬਿਧਿ ਹਮ ਹੂੰ ਲਖਿ ਪਾਈ।","roman":"Jaa bidhi kaaran baat banaavat so bidhi ham hoon lakhi paaee |","meaning_en":"The reason for which you make up this talk, we too have understood.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਭੇਦ ਕਰੋ ਹਮ ਸੋ ਤੁਮ ਨਾਹਕ ਬਾਤ ਇਹੈ ਮਨ ਮੈ ਤੁਹਿ ਆਈ।","roman":"Bhed karo ham so tum naahak baat ihai man mai tuhi aaee |","meaning_en":"You keep secrets from us for nothing; this notion has come into your head.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਸਉਹ ਲਗੈ ਹਮ ਠਾਕੁਰ ਕੀ ਜੁ ਰਹੈ ਤੁਮਰੀ ਬਿਨੁ ਮਾਤ ਸੁਨਾਈ। ੨੫੯।","roman":"Sauh lagai ham thaakur kee ju rahai tumree binu maat sunaaee | 259 |","meaning_en":"We swear by the Lord, we will not rest without telling your mother.'","page":373,"meaning_status":"draft","note":"Read as a threat to tell his mother; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ ਗੁਪੀਆ ਸੋ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ ਗੁਪੀਆ ਸੋ","roman":"Kaanh baach gupeeaa so","meaning_en":"Kanh said to the gopis:","page":373,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":373,"meaning_status":"draft"},{"type":"verse","number":[260],"number_text":"੨੬੦।","page":373,"lines":[{"gurmukhi":"ਮਾ ਸੁਨਿ ਹੈ ਤਬ ਕਾ ਕਰਿ ਹੈ ਹਮਰੋ ਸੁਨਿ ਲੇਹੁ ਸਭੈ ਬ੍ਰਿਜ ਨਾਰੀ।","roman":"Maa suni hai tab kaa kari hai hamro suni lehu sabhai brij naaree |","meaning_en":"'If my mother hears, what will she do to me? Listen, all you women of Braj.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਬਾਤ ਕਹੀ ਤੁਮ ਮੂੜਨ ਕੀ ਹਮ ਜਾਨਤ ਹੈ ਤੁਮ ਹੋ ਸਭ ਬਾਰੀ।","roman":"Baat kahee tum mooran kee ham jaanat hai tum ho sabh baaree |","meaning_en":"You have talked like fools; I know you are all just young girls.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਸੀਖਤ ਹੋ ਰਸ ਰੀਤਿ ਅਬੈ ਇਹ ਕਾਨ੍ਹ ਕਹੀ ਤੁਮ ਹੋ ਮੁਹਿ ਪਿਆਰੀ।","roman":"Seekhat ho ras reeti abai ih kaanh kahee tum ho muhi piaaree |","meaning_en":"You are only now learning the ways of love,' said Kanh; 'you are dear to me.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਖੇਲਨ ਕਾਰਨ ਕੋ ਹਮ ਹੂੰ ਜੁ ਹਰੀ ਛਲ ਕੈ ਤੁਮ ਸੁੰਦਰ ਸਾਰੀ। ੨੬੦।","roman":"Khelan kaaran ko ham hoon ju haree chhal kai tum sundar saaree | 260 |","meaning_en":"It was for play that I took your lovely saris by a trick.'","page":373,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"The gopis said:","page":373,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":373,"meaning_status":"draft"},{"type":"verse","number":[261],"number_text":"੨੬੧।","page":373,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਮੁਖ ਤੇ ਇਮ ਗੋਪਿਨ ਬਾਤ ਇਸੀ ਮਨੁ ਏ ਪਟ ਦੈਹੋ।","roman":"Pheri kahee mukh te im gopin baat isee manu e pat daiho |","meaning_en":"Again the gopis said: 'Is this what is in your mind? Give us the clothes.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਸਉਹ ਕਰੋ ਮੁਸਲੀਧਰ ਕੀ ਜਸੁਧਾ ਨੰਦ ਕੀ ਹਮ ਕੋ ਡਰ ਕੈਹੋ।","roman":"Sauh karo musleedhar kee jasudhaa nand kee ham ko dar kaiho |","meaning_en":"We swear by Balram, by Yashoda and by Nand; what fear do we have?","page":373,"meaning_status":"draft","note":"ਮੁਸਲੀਧਰ: Balram. ਡਰ ਕੈਹੋ: sense uncertain."},{"gurmukhi":"ਕਾਨ੍ਹ ਬਿਚਾਰਿ ਪਿਖੋ ਮਨ ਮੈ ਇਨ ਬਾਤਨ ਤੇ ਤੁਮ ਨ ਕਿਛੁ ਪੈਹੋ।","roman":"Kaanh bichaari pikho man mai in baatan te tum na kichhu paiho |","meaning_en":"Kanh, think it over in your mind: you will gain nothing by this talk.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਦੇਹੁ ਕਹਿਯੋ ਜਲ ਮੈ ਹਮ ਕੋ ਇਹ ਦੇਹਿ ਅਸੀਸ ਸਭੈ ਤੁਹਿ ਜੈਹੋ। ੨੬੧।","roman":"Dehu kahiyo jal mai ham ko ih dehi asees sabhai tuhi jaiho | 261 |","meaning_en":"Give them to us in the water, we say; we will all bless you and go.'","page":373,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"The gopis said:","page":373,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":373,"meaning_status":"draft"},{"type":"verse","number":[262],"number_text":"੨੬੨।","page":373,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਮੁਖ ਤੇ ਮਿਲਿ ਗੋਪਨ ਨੇਹ ਲਗੈ ਹਰਿ ਜੀ ਨਹਿ ਜੋਰੀ।","roman":"Pheri kahee mukh te mili gopan neh lagai hari jee nahi joree |","meaning_en":"Again the gopis said together, 'Love cannot be made by force, Hari.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਨੈਨਨ ਸਾਥ ਲਗੈ ਸੋਊ ਨੇਹੁ ਕਹੈ ਮੁਖ ਤੇ ਇਹ ਸਾਵਲ ਗੋਰੀ।","roman":"Nainan saath lagai so'oo nehu kahai mukh te ih saaval goree |","meaning_en":"Love takes hold through the eyes,' say the dark and fair ones.","page":373,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਕੈ ਇਹ ਬਾਤ ਸੁਨੋ ਰਸ ਰੀਤਿ ਕਹੋ ਮਮ ਹੋਰੀ।","roman":"Kaanh kahee hasi kai ih baat suno ras reeti kaho mam horee |","meaning_en":"Kanh said, laughing, 'Listen: let me tell you the way of love differently.","page":373,"meaning_status":"draft","note":"ਮਮ ਹੋਰੀ: sense uncertain."},{"gurmukhi":"ਆਖਨ ਸਾਥ ਲਗੈ ਟਕਵਾ ਫੁਨਿ ਹਾਥਨ ਸਾਥ ਲਗੈ ਸੁਭ ਸੋਰੀ। ੨੬੨।","roman":"Aakhan saath lagai takvaa phuni haathan saath lagai subh soree | 262 |","meaning_en":"First the eyes meet in a gaze, and then the hands meet in delight.'","page":373,"meaning_status":"draft","note":"ਟਕਵਾ, ਸੋਰੀ: sense uncertain."}]},{"type":"verse","number":[263],"number_text":"੨੬੩।","page":374,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਮੁਖਿ ਤੇ ਗੁਪੀਆ ਹਮਰੇ ਪਟ ਦੇਹੁ ਕਹਿਯੋ ਨੰਦ ਲਾਲਾ।","roman":"Pheri kahee mukhi te gupeeaa hamre pat dehu kahiyo nand laalaa |","meaning_en":"Again the gopis said, 'Give us our clothes, O darling of Nand.","page":374,"meaning_status":"draft"},{"gurmukhi":"ਫੇਰਿ ਇਸਨਾਨ ਕਰੈ ਨ ਇਹਾ ਕਹਿ ਹੈ ਹਮਿ ਲੋਗਨ ਆਛਨ ਬਾਲਾ।","roman":"Pheri isnaan karai na ihaa kahi hai hami logan aachhan baalaa |","meaning_en":"We will not bathe here again; we shall tell people you are a fine boy.'","page":374,"meaning_status":"draft","note":"ਆਛਨ ਬਾਲਾ: sense uncertain."},{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਹਮ ਕੋ ਕਰ ਬਾਹਰ ਹ੍ਵੈ ਜਲ ਤੇ ਤਤਕਾਲਾ।","roman":"Jori pranaam karo ham ko kar baahar hvai jal te tatkaalaa |","meaning_en":"'Join your hands and bow to me, coming out of the water at once.'","page":374,"meaning_status":"draft","note":"Read as Kanh's words."},{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਕੈ ਮੁਖਿ ਤੈ ਕਰਿ ਹੋ ਨਹੀ ਢੀਲ ਦੇਉ ਪਟ ਹਾਲਾ। ੨੬੩।","roman":"Kaanh kahee hasi kai mukhi tai kari ho nahee dheel deu pat haalaa | 263 |","meaning_en":"Kanh said, laughing, 'I will make no delay; I will give the clothes at once.'","page":374,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":374,"meaning_status":"draft"},{"type":"verse","number":[264],"number_text":"੨੬੪।","page":374,"lines":[{"gurmukhi":"ਮੰਤ੍ਰ ਸਭਨ ਮਿਲਿ ਇਹ ਕਰਿਯੋ ਜਲ ਕੋ ਤਜਿ ਸਭ ਨਾਰਿ।","roman":"Mantr sabhan mili ih kariyo jal ko taji sabh naari |","meaning_en":"All the women took counsel together, to leave the water;","page":374,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨਰ ਕੀ ਬਿਨਤੀ ਕਰੋ ਕੀਨੋ ਇਹੈ ਬਿਚਾਰ। ੨੬੪।","roman":"Kaanar kee bintee karo keeno ihai bichaar | 264 |","meaning_en":"'Let us plead with Kanh': this is what they decided.","page":374,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":374,"meaning_status":"draft"},{"type":"verse","number":[265],"number_text":"੨੬੫।","page":374,"lines":[{"gurmukhi":"ਦੈ ਅਗੂਆ ਪਿਛੂਆ ਅਪੁਨੇ ਕਰ ਪੈ ਸਭ ਹੀ ਜਲ ਤਿਆਗਿ ਖਰੀ ਹੈ।","roman":"Dai agooaa pichhooaa apune kar pai sabh hee jal tiaagi kharee hai |","meaning_en":"Putting their hands before and behind them, they all left the water and stood up.","page":374,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨ ਕੇ ਪਾਇ ਪਰੀ ਬਹੁ ਬਾਰਨ ਅਉ ਬਿਨਤੀ ਬਹੁ ਭਾਤਿ ਕਰੀ ਹੈ।","roman":"Kaan ke paai paree bahu baaran au bintee bahu bhaati karee hai |","meaning_en":"They fell at Kanh's feet many times and pleaded in many ways:","page":374,"meaning_status":"draft"},{"gurmukhi":"ਦੇਹੁ ਕਹਿਯੋ ਹਮਰੀ ਸਰ੍ਹੀਆ ਤੁਮ ਜੋ ਕਰਿ ਕੈ ਛਲ ਸਾਥ ਹਰੀ ਹੈ।","roman":"Dehu kahiyo hamree sarheeaa tum jo kari kai chhal saath haree hai |","meaning_en":"'Give us our saris, which you have taken by a trick.","page":374,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਕਹਿ ਹੋ ਮਨਿ ਹੈ ਹਮ ਸੋ ਅਤਿ ਹੀ ਸਭ ਸੀਤਹਿ ਸਾਥ ਠਰੀ ਹੈ। ੨੬੫।","roman":"Je kahi ho mani hai ham so ati hee sabh seethi saath tharee hai | 265 |","meaning_en":"Whatever you say we will obey; we are all frozen with the cold.'","page":374,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"Kanh said:","page":374,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":374,"meaning_status":"draft"},{"type":"verse","number":[266],"number_text":"੨੬੬।","page":374,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਬਾਤ ਤਿਨੈ ਕਹਿ ਹੈ ਹਮ ਜੋ ਤੁਮ ਸੋ ਮਨ ਹੋ।","roman":"Kaanh kahee hasi baat tinai kahi hai ham jo tum so man ho |","meaning_en":"Kanh said to them, laughing, 'I will tell you what is in my mind.","page":374,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਹੀ ਮੁਖ ਚੂਮਨ ਦੇਹੁ ਕਹਿਯੋ ਚੁਮ ਹੈ ਹਮ ਹੂੰ ਤੁਮ ਹੂੰ ਗਨਿ ਹੋ।","roman":"Sabh hee mukh chooman dehu kahiyo chum hai ham hoon tum hoon gani ho |","meaning_en":"All of you, let me kiss your faces; I will kiss you and count you one by one.","page":374,"meaning_status":"draft","note":"ਗਨਿ ਹੋ: read as 'I will count'; uncertain."},{"gurmukhi":"ਅਰੁ ਤੋਰਨ ਦੇਹੁ ਕਹਿਯੋ ਸਭ ਹੀ ਕੁਚ ਨਾਤਰ ਹਉ ਤੁਮ ਕੋ ਹਨਿ ਹੋ।","roman":"Aru toran dehu kahiyo sabh hee kuch naatar hau tum ko hani ho |","meaning_en":"And all of you, let me touch your breasts, or else I will strike you.","page":374,"meaning_status":"draft","note":"ਤੋਰਨ: read as 'to press, touch'; uncertain."},{"gurmukhi":"ਤਬ ਹੀ ਪਟ ਦੇਉ ਸਭੈ ਤੁਮਰੇ ਇਹ ਝੂਠ ਨਹੀ ਸਤਿ ਕੈ ਜਨਿ ਹੋ। ੨੬੬।","roman":"Tab hee pat deu sabhai tumre ih jhooth nahee sati kai jani ho | 266 |","meaning_en":"Only then will I give all your clothes; this is no lie, know it is true.'","page":374,"meaning_status":"draft"}]},{"type":"verse","number":[267],"number_text":"੨੬੭।","page":374,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਮੁਖ ਤੇ ਹਰਿ ਜੀ ਸੁਨਿ ਰੀ ਇਕ ਬਾਤ ਕਹੋ ਸੰਗ ਤੇਰੇ।","roman":"Pheri kahee mukh te hari jee suni ree ik baat kaho sang tere |","meaning_en":"Again Hari said, 'Listen, girl, I tell you one thing.","page":374,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਕਰ ਸੋ ਤੁਮ ਕਾਮ ਕਰਾ ਉਪਜੀ ਜੀਅ ਮੇਰੇ।","roman":"Jori pranaam karo kar so tum kaam karaa upjee jeea mere |","meaning_en":"Join your hands and bow to me; the power of love has arisen in my heart.","page":374,"meaning_status":"draft","note":"ਕਾਮ ਕਰਾ: read as 'the force of desire'."},{"gurmukhi":"ਤੌ ਹਮ ਬਾਤ ਕਹੀ ਤੁਮ ਸੋ ਜਬ ਘਾਤ ਬਨੀ ਸੁਭ ਠਉਰ ਅਕੇਰੇ।","roman":"Tau ham baat kahee tum so jab ghaat banee subh thaur akere |","meaning_en":"So I spoke to you, now that a chance has come in a lovely place, alone.","page":374,"meaning_status":"draft"},{"gurmukhi":"ਦਾਨ ਲਹੈ ਜੀਅ ਕੋ ਹਮ ਹੂੰ ਹਸਿ ਕਾਨ੍ਹ ਕਹੀ ਤੁਮਰੋ ਤਨ ਹੇਰੇ। ੨੬੭।","roman":"Daan lahai jeea ko ham hoon hasi kaanh kahee tumro tan here | 267 |","meaning_en":"I would receive the gift my heart desires,' said Kanh, laughing, looking at their bodies.","page":374,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"The poet said:","page":374,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":374,"meaning_status":"draft"},{"type":"verse","number":[268],"number_text":"੨੬੮।","page":374,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਜਬੈ ਗੋਪੀ ਸਭੈ ਦੇਖਿਯੋ ਨੈਨ ਨਚਾਤ।","roman":"Kaanh jabai gopee sabhai dekhiyo nain nachaat |","meaning_en":"When all the gopis saw Kanh making his eyes dance,","page":374,"meaning_status":"draft"},{"gurmukhi":"ਹ੍ਵੈ ਪ੍ਰਸੰਨਿ ਕਹਨੇ ਲਗੀ ਸਭੈ ਸੁਧਾ ਸੀ ਬਾਤ। ੨੬੮।","roman":"Hvai prasanni kahne lagee sabhai sudhaa see baat | 268 |","meaning_en":"they were pleased and all began to speak words like nectar.","page":374,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","roman":"Gopee baach kaanh so","meaning_en":"The gopis said to Kanh:","page":375,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":375,"meaning_status":"draft"},{"type":"verse","number":[269],"number_text":"੨੬੯।","page":375,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਹਿਕ੍ਰਮ ਥੋਰੀ ਤੁਮੈ ਖੇਲਹੁ ਨ ਅਪਨੋ ਘਰ ਕਾਹੋ।","roman":"Kaanh bahikram thoree tumai khelhu na apno ghar kaaho |","meaning_en":"'Kanh, you are young in years; why don't you go and play at your own home?","page":375,"meaning_status":"draft","note":"ਬਹਿਕ੍ਰਮ: read as 'age' (vayakram); uncertain."},{"gurmukhi":"ਨੰਦ ਸੁਨੈ ਜਸੁਧਾ ਤਪਤੈ ਤਿਹ ਤੇ ਤੁਮ ਕਾਨ੍ਹ ਭਏ ਹਰਕਾ ਹੋ।","roman":"Nand sunai jasudhaa taptai tih te tum kaanh bhae harkaa ho |","meaning_en":"If Nand hears, Yashoda will burn with anger; because of this, Kanh, you will be scolded.","page":375,"meaning_status":"draft","note":"ਹਰਕਾ: sense uncertain; may mean 'mischievous'."},{"gurmukhi":"ਨੇਹੁੰ ਲਗੈ ਨਹ ਜੋਰ ਭਏ ਤੁਮ ਨੇਹੁ ਲਗਾਵਤ ਹੋ ਬਰ ਕਾਹੋ।","roman":"Nehun lagai nah jor bhae tum nehu lagaavat ho bar kaaho |","meaning_en":"Love does not come by force, yet you try to make love by force.","page":375,"meaning_status":"draft","note":"ਬਰ ਕਾਹੋ: read as 'by force'; uncertain."},{"gurmukhi":"ਲੇਹੁ ਕਹਾ ਇਨ ਬਾਤਨ ਤੇ ਰਸ ਜਾਨਤ ਕਾ ਅਜਹੂੰ ਲਰਕਾ ਹੋ। ੨੬੯।","roman":"Lehu kahaa in baatan te ras jaanat kaa ajhoon larkaa ho | 269 |","meaning_en":"What will you get from such talk? What do you know of love? You are still a boy.'","page":375,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":375,"meaning_status":"draft"},{"type":"verse","number":[270],"number_text":"੨੭੦।","page":375,"lines":[{"gurmukhi":"ਕਮਲ ਸੇ ਆਨਨ ਕੁਰੰਗਨ ਸੇ ਨੇਤ੍ਰਨ ਸੋ ਤਨ ਕੀ ਪ੍ਰਭਾ ਮੈ ਸਾਰੇ ਭਾਵਨ ਸੋ ਭਰੀਆ।","roman":"Kamal se aanan kurangan se netran so tan kee prabhaa mai saare bhaavan so bhareeaa |","meaning_en":"With faces like lotuses and eyes like does', their bodies radiant and full of every feeling,","page":375,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਤ ਹੈ ਗੁਪੀਆ ਪ੍ਰਸੰਨ ਭਈ ਐਸੀ ਭਾਤਿ ਚੰਦ੍ਰਮਾ ਚਰ੍ਹੈ ਤੇ ਜਿਉ ਬਿਰਾਜੈ ਸੇਤ ਹਰੀਆ।","roman":"Raajat hai gupeeaa prasann bhaee aisee bhaati chandramaa charhai te jiu biraajai set hareeaa |","meaning_en":"the gopis, pleased, look as splendid as white lilies shining when the moon has risen.","page":375,"meaning_status":"draft","note":"ਸੇਤ ਹਰੀਆ: read as 'white lilies'; uncertain."},{"gurmukhi":"ਰਸ ਹੀ ਕੀ ਬਾਤੈ ਰਸ ਰੀਤਿ ਹੀ ਕੇ ਪ੍ਰੇਮ ਹੂੰ ਮੈ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਸਾਥ ਕਾਨ੍ਹ ਜੂ ਕੇ ਖਰੀਆ।","roman":"Ras hee kee baatai ras reeti hee ke prem hoon mai kahai kabi syaam saath kaanh joo ke khareeaa |","meaning_en":"Talking only of love, absorbed in the ways of love, says the poet Shyam, they stand with Kanh,","page":375,"meaning_status":"draft"},{"gurmukhi":"ਮਦਨ ਕੇ ਹਾਰਨ ਬਨਾਇਬੇ ਕੇ ਕਾਜ ਮਾਨੋ ਹਿਤ ਕੈ ਪਰੋਵਤ ਹੈ ਮੋਤਿਨ ਕੀ ਲਰੀਆ। ੨੭੦।","roman":"Madan ke haaran banaaibe ke kaaj maano hit kai parovat hai motin kee lareeaa | 270 |","meaning_en":"as if, to make garlands for Love, they were lovingly threading strings of pearls.","page":375,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":375,"meaning_status":"draft"},{"type":"verse","number":[271],"number_text":"੨੭੧।","page":375,"lines":[{"gurmukhi":"ਕਾਹੇ ਕੋ ਕਾਨ੍ਹ ਜੂ ਕਾਮ ਕੇ ਬਾਨ ਲਗਾਵਤ ਹੋ ਤਨ ਕੇ ਧਨੁ ਭਉਹੈ।","roman":"Kaahe ko kaanh joo kaam ke baan lagaavat ho tan ke dhanu bhauhai |","meaning_en":"'Why, Kanh, do you shoot the arrows of love, drawing the bow of your eyebrows?","page":375,"meaning_status":"draft"},{"gurmukhi":"ਕਾਹੇ ਕਉ ਨੇਹੁ ਲਗਾਵਤ ਹੋ ਮੁਸਕਾਵਤ ਹੋ ਚਲਿ ਆਵਤ ਸਉਹੈ।","roman":"Kaahe kau nehu lagaavat ho muskaavat ho chali aavat sauhai |","meaning_en":"Why do you make us love you, smiling as you come walking towards us?","page":375,"meaning_status":"draft"},{"gurmukhi":"ਕਾਹੇ ਕਉ ਪਾਗ ਧਰੋ ਤਿਰਛੀ ਅਰੁ ਕਾਹੇ ਭਰੋ ਤਿਰਛੀ ਤੁਮ ਗਉਹੈ।","roman":"Kaahe kau paag dharo tirchhee aru kaahe bharo tirchhee tum gauhai |","meaning_en":"Why do you wear your turban at a slant, and why do you cast slanting looks?","page":375,"meaning_status":"draft","note":"ਗਉਹੈ: read as 'glances' or 'gait'; uncertain."},{"gurmukhi":"ਕਾਹੇ ਰਿਝਾਵਤ ਹੌ ਮਨ ਭਾਵਤ ਆਹਿ ਦਿਵਵਾਤ ਹੈ ਹਮ ਸਉਹੈ। ੨੭੧।","roman":"Kaahe rijhaavat hau man bhaavat aahi divvaat hai ham sauhai | 271 |","meaning_en":"Why do you charm us as you please and make us sigh? We swear it.'","page":375,"meaning_status":"draft","note":"ਆਹਿ ਦਿਵਵਾਤ ਹੈ: read as 'makes us sigh'; uncertain."}]},{"type":"verse","number":[272],"number_text":"੨੭੨।","page":375,"lines":[{"gurmukhi":"ਬਾਤ ਸੁਨੀ ਹਰਿ ਕੀ ਜਬ ਸ੍ਰਉਨਨ ਰੀਝ ਹਸੀ ਸਭ ਹੀ ਬ੍ਰਿਜ ਬਾਮੈ।","roman":"Baat sunee hari kee jab sraunan reejh hasee sabh hee brij baamai |","meaning_en":"When they heard Hari's words with their ears, all the women of Braj laughed with delight.","page":375,"meaning_status":"draft"},{"gurmukhi":"ਠਾਢੀ ਭਈ ਤਰੁ ਤੀਰ ਤਬੈ ਹਰੂਏ ਹਰੂਏ ਚਲ ਕੈ ਗਜ ਗਾਮੈ।","roman":"Thaadhee bhaee taru teer tabai harooe harooe chal kai gaj gaamai |","meaning_en":"Then they came and stood near the tree, walking slowly, slowly, with the gait of elephants.","page":375,"meaning_status":"draft"},{"gurmukhi":"ਬੇਰਿ ਬਨੇ ਤਿਨ ਨੇਤ੍ਰਨ ਕੇ ਜਨੁ ਮੈਨ ਬਨਾਇ ਧਰੇ ਇਹ ਦਾਮੈ।","roman":"Beri bane tin netran ke janu main banaai dhare ih daamai |","meaning_en":"Their eyes became like snares, as if Love had fashioned them and laid them out.","page":375,"meaning_status":"draft","note":"ਬੇਰਿ, ਦਾਮੈ: read as 'snares, nets'; uncertain."},{"gurmukhi":"ਸ੍ਯਾਮ ਰਸਾਤੁਰ ਪੇਖਤ ਯੌ ਜਿਮ ਟੂਟਤ ਬਾਜ ਛੁਧਾ ਜੁਤ ਤਾਮੈ। ੨੭੨।","roman":"Syaam rasaatur pekhat yau jim tootat baaj chhudhaa jut taamai | 272 |","meaning_en":"Shyam, full of longing, gazes at them like a hungry hawk swooping down on them.","page":375,"meaning_status":"draft"}]},{"type":"verse","number":[273],"number_text":"੨੭੩।","page":375,"lines":[{"gurmukhi":"ਕਾਮ ਸੇ ਰੂਪ ਕਲਾਨਿਧਿ ਸੇ ਮੁਖ ਕੀਰ ਸੇ ਨਾਕ ਕੁਰੰਗ ਸੇ ਨੈਨਨ।","roman":"Kaam se roop kalaanidhi se mukh keer se naak kurang se nainan |","meaning_en":"With beauty like Love's, faces like the moon, noses like parrots', eyes like deer,","page":375,"meaning_status":"draft","note":"ਕਲਾਨਿਧਿ: the moon."},{"gurmukhi":"ਕੰਚਨ ਸੇ ਤਨ ਦਾਰਿਮ ਦਾਤ ਕਪੋਤ ਸੇ ਕੰਠ ਸੁ ਕੋਕਿਲ ਬੈਨਨ।","roman":"Kanchan se tan daarim daat kapot se kanth su kokil bainan |","meaning_en":"bodies like gold, teeth like pomegranate seeds, throats like doves', voices like the koel,","page":375,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨ੍ਹ ਲਗਿਯੋ ਕਹਨੇ ਤਿਨ ਸੋ ਹਸਿ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਸਹਾਇਕ ਧੈਨਨ।","roman":"Kaanh lagiyo kahne tin so hasi kai kabi syaam sahaaik dhainan |","meaning_en":"Kanh, the helper of the cows, says the poet Shyam, began to speak to them, laughing:","page":375,"meaning_status":"draft","note":"ਧੈਨਨ: read as 'cows'; uncertain."},{"gurmukhi":"ਮੋਹਿ ਲਯੋ ਸਭ ਹੀ ਮਨੁ ਮੇਰੋ ਸੁ ਭਉਹ ਨਚਾਇ ਤੁਮੈ ਸੰਗ ਸੈਨਨ। ੨੭੩।","roman":"Mohi layo sabh hee manu mero su bhauh nachaai tumai sang sainan | 273 |","meaning_en":"'Making your eyebrows dance with signals, you have captivated my whole heart.'","page":375,"meaning_status":"draft"}]},{"type":"verse","number":[274],"number_text":"੨੭੪।","page":375,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਡੇ ਰਸ ਕੇ ਹਿਰੀਆ ਸਬ ਹੀ ਜਲ ਬੀਚ ਅਚਾਨਕ ਹੇਰੀ।","roman":"Kaanh bade ras ke hireeaa sab hee jal beech achaanak heree |","meaning_en":"Kanh, a great stealer of love, had suddenly seen them all in the water.","page":375,"meaning_status":"draft","note":"ਹਿਰੀਆ: read as 'stealer' or 'seeker'; uncertain."},{"gurmukhi":"ਸਉਹ ਤੁਮੈ ਜਸੁਧਾ ਕਹੁ ਬਾਤ ਕਿਸਾਰਥ ਕੌ ਇਹ ਜਾ ਹਮ ਘੇਰੀ।","roman":"Sauh tumai jasudhaa kahu baat kisaarath kau ih jaa ham gheree |","meaning_en":"'We swear by Yashoda, tell us: for what purpose have you cornered us here?","page":375,"meaning_status":"draft"},{"gurmukhi":"ਦੇਹੁ ਕਹਿਯੋ ਸਭ ਹੀ ਹਮਰੇ ਪਟ ਹੋਹਿੰ ਸਭੈ ਤੁਮਰੀ ਹਮ ਚੇਰੀ।","roman":"Dehu kahiyo sabh hee hamre pat hohin sabhai tumree ham cheree |","meaning_en":"Give us all our clothes, we say; we will all be your servants.","page":376,"meaning_status":"draft"},{"gurmukhi":"ਕੈਸੇ ਪ੍ਰਨਾਮ ਕਰੈ ਤੁਮ ਕੋ ਅਤਿ ਲਾਜ ਕਰੈ ਹਰਿ ਜੀ ਹਮ ਤੇਰੀ। ੨੭੪।","roman":"Kaise pranaam karai tum ko ati laaj karai hari jee ham teree | 274 |","meaning_en":"How can we bow to you? We feel very shy of you, Hari.'","page":376,"meaning_status":"draft"}]},{"type":"verse","number":[275],"number_text":"੨੭੫।","page":376,"lines":[{"gurmukhi":"ਪਾਪ ਕਰਿਯੋ ਹਰਿ ਕੈ ਤੁਮਰੇ ਪਟ ਅਉ ਤਰੁ ਪੈ ਚੜਿ ਸੀਤ ਸਹਾ ਹੈ।","roman":"Paap kariyo hari kai tumre pat au taru pai chari seet sahaa hai |","meaning_en":"'I have done wrong in taking your clothes, and sitting up in the tree I have endured the cold.","page":376,"meaning_status":"draft","note":"Read as Kanh's words; speaker uncertain."},{"gurmukhi":"ਜੋ ਹਮ ਪ੍ਰੇਮ ਛਕੇ ਅਤਿ ਹੀ ਤੁਮ ਕੋ ਹਮ ਢੂੰਢਤ ਢੂੰਢ ਲਹਾ ਹੈ।","roman":"Jo ham prem chhake ati hee tum ko ham dhoondhat dhoondh lahaa hai |","meaning_en":"Since I am so steeped in love, I searched and searched and found you.","page":376,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰ ਪ੍ਰਨਾਮ ਕਰੋ ਹਮ ਕੋ ਕਰ ਸਉਹ ਲਗੈ ਤੁਮ ਮੇਰੀ ਹਹਾ ਹੈ।","roman":"Jor pranaam karo ham ko kar sauh lagai tum meree hahaa hai |","meaning_en":"Join your hands and bow to me; I swear, I beg of you.'","page":376,"meaning_status":"draft","note":"ਹਹਾ: an entreaty."},{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਬਾਤ ਸੁਨੋ ਸੁਭ ਚਾਰ ਭਈ ਤੁ ਬਿਚਾਰ ਕਹਾ ਹੈ। ੨੭੫।","roman":"Kaanh kahee hasi baat suno subh chaar bhaee tu bichaar kahaa hai | 275 |","meaning_en":"Kanh said, laughing, 'Listen: it is a good thing, so what is there to think about?'","page":376,"meaning_status":"draft","note":"ਸੁਭ ਚਾਰ: sense uncertain."}]},{"type":"verse","number":[276],"number_text":"੨੭੬।","page":376,"lines":[{"gurmukhi":"ਸੰਕ ਕਰੋ ਹਮ ਤੇ ਨ ਕਛੂ ਅਰੁ ਲਾਜ ਕਛੂ ਜੀਅ ਮੈ ਨਹੀ ਕੀਜੈ।","roman":"Sank karo ham te na kachhoo aru laaj kachhoo jeea mai nahee keejai |","meaning_en":"'Have no fear of me at all, and feel no shame in your heart.","page":376,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਹਮ ਕੋ ਕਰ ਦਾਸਨ ਕੀ ਬਿਨਤੀ ਸੁਨਿ ਲੀਜੈ।","roman":"Jori pranaam karo ham ko kar daasan kee bintee suni leejai |","meaning_en":"Join your hands and bow to me; listen to the plea of your servant.'","page":376,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਕੈ ਤਿਨ ਸੋ ਤੁਮਰੇ ਮ੍ਰਿਗ ਸੇ ਦ੍ਰਿਗ ਦੇਖਤ ਜੀਜੈ।","roman":"Kaanh kahee hasi kai tin so tumre mrig se drig dekhat jeejai |","meaning_en":"Kanh said to them, laughing, 'I live by seeing your deer-like eyes.","page":376,"meaning_status":"draft"},{"gurmukhi":"ਡੇਰਨ ਨਾਹਿ ਕਹੈ ਤੁਮਰੇ ਇਹ ਤੇ ਤੁਮਰੋ ਕਛੂ ਨਾਹਿਨ ਛੀਜੈ। ੨੭੬।","roman":"Deran naahi kahai tumre ih te tumro kachhoo naahin chheejai | 276 |","meaning_en":"I will not tell anything at your homes; nothing of yours will be lost by this.'","page":376,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":376,"meaning_status":"draft"},{"type":"verse","number":[277],"number_text":"੨੭੭।","page":376,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਜਬੈ ਪਟ ਨ ਦਏ ਤਬ ਗੋਪੀ ਸਭ ਹਾਰਿ।","roman":"Kaanh jabai pat na dae tab gopee sabh haari |","meaning_en":"When Kanh would not give the clothes, all the gopis gave in;","page":376,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨ੍ਹਿ ਕਹੈ ਸੋ ਕੀਜੀਐ ਕੀਨੋ ਇਹੈ ਬਿਚਾਰ। ੨੭੭।","roman":"Kaanhi kahai so keejeeai keeno ihai bichaar | 277 |","meaning_en":"'Let us do what Kanh says': this is what they decided.","page":376,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":376,"meaning_status":"draft"},{"type":"verse","number":[278],"number_text":"੨੭੮।","page":376,"lines":[{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਹਰਿ ਕੋ ਕਰ ਆਪਸ ਮੈ ਕਹਿ ਕੈ ਮੁਸਕਾਨੀ।","roman":"Jori pranaam karo hari ko kar aapas mai kahi kai muskaanee |","meaning_en":"Saying among themselves, 'Let us join our hands and bow to Hari,' they smiled.","page":376,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਲਗੀ ਕਹਨੇ ਮੁਖ ਤੇ ਸਭ ਹੀ ਗੁਪੀਆ ਮਿਲਿ ਅੰਮ੍ਰਿਤ ਬਾਨੀ।","roman":"Syaam lagee kahne mukh te sabh hee gupeeaa mili anmrit baanee |","meaning_en":"All the gopis together began to speak nectar-sweet words to Shyam:","page":376,"meaning_status":"draft"},{"gurmukhi":"ਹੋਹੁ ਪ੍ਰਸੰਨ੍ਯ ਕਹਿਯੋ ਹਮ ਪੈ ਕਰੁ ਬਾਤ ਕਹੀ ਤੁਮ ਸੋ ਹਮ ਮਾਨੀ।","roman":"Hohu prasanny kahiyo ham pai karu baat kahee tum so ham maanee |","meaning_en":"'Be pleased with us; what you said, we have accepted.","page":376,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤਰ ਨਾਹਿ ਰਹਿਯੋ ਇਹ ਜਾ ਅਬ ਸੋਊ ਭਲੀ ਤੁਮ ਜੋ ਮਨਿ ਭਾਨੀ। ੨੭੮।","roman":"Antar naahi rahiyo ih jaa ab so'oo bhalee tum jo mani bhaanee | 278 |","meaning_en":"Now no distance remains between us here; whatever pleases your heart is good.'","page":376,"meaning_status":"draft"}]},{"type":"verse","number":[279],"number_text":"੨੭੯।","page":376,"lines":[{"gurmukhi":"ਕਾਮ ਕੇ ਬਾਨ ਬਨੀ ਬਰਛੀ ਭਰੁਟੇ ਧਨੁ ਸੇ ਦ੍ਰਿਗ ਸੁੰਦਰ ਤੇਰੇ।","roman":"Kaam ke baan banee barchhee bharute dhanu se drig sundar tere |","meaning_en":"'Your lovely eyes are arrows and spears of Love, and your eyebrows are like bows.","page":376,"meaning_status":"draft","note":"Read as Kanh's reply; speaker uncertain."},{"gurmukhi":"ਆਨਨ ਹੈ ਸਸਿ ਸੋ ਅਲਕੈ ਹਰਿ ਮੋਹਿ ਰਹੈ ਮਨ ਰੰਚਕ ਹੇਰੇ।","roman":"Aanan hai sasi so alkai hari mohi rahai man ranchak here |","meaning_en":"Your face is like the moon, and your locks, glimpsed even a little, captivate the mind.","page":376,"meaning_status":"draft","note":"ਹਰਿ ਮੋਹਿ: read as 'steal and charm'; uncertain."},{"gurmukhi":"ਤਉ ਤੁਮ ਸਾਥ ਕਰੀ ਬਿਨਤੀ ਜਬ ਕਾਮ ਕਰਾ ਉਪਜੀ ਜੀਅ ਮੇਰੇ।","roman":"Tau tum saath karee bintee jab kaam karaa upjee jeea mere |","meaning_en":"So I made my request to you when the power of love arose in my heart.","page":376,"meaning_status":"draft"},{"gurmukhi":"ਚੁੰਬਨ ਦੇਹੁ ਕਹਿਓ ਸਭ ਹੀ ਮੁਖ ਸਉਹ ਹਮੈ ਕਹਿ ਹੈ ਨਹਿ ਡੇਰੇ। ੨੭੯।","roman":"Chunban dehu kahio sabh hee mukh sauh hamai kahi hai nahi dere | 279 |","meaning_en":"All of you give me kisses on your faces; I swear I will not tell at your homes.'","page":376,"meaning_status":"draft"}]},{"type":"verse","number":[280],"number_text":"੨੮੦।","page":376,"lines":[{"gurmukhi":"ਹੋਇ ਪ੍ਰਸੰਨ੍ਯ ਸਭੈ ਗੁਪੀਆ ਮਿਲਿ ਮਾਨ ਲਈ ਜੋਊ ਕਾਨ੍ਹ ਕਹੀ ਹੈ।","roman":"Hoi prasanny sabhai gupeeaa mili maan laee jo'oo kaanh kahee hai |","meaning_en":"All the gopis together, pleased, accepted what Kanh had said.","page":376,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰਿ ਹੁਲਾਸ ਬਢਿਯੋ ਜੀਅ ਮੈ ਗਿਨਤੀ ਸਰਿਤਾ ਮਗ ਨੇਹ ਬਹੀ ਹੈ।","roman":"Jori hulaas badhiyo jeea mai gintee saritaa mag neh bahee hai |","meaning_en":"Great joy swelled in their hearts; a river of love flowed along its course beyond counting.","page":376,"meaning_status":"draft","note":"ਗਿਨਤੀ ਸਰਿਤਾ ਮਗ: sense uncertain."},{"gurmukhi":"ਸੰਕ ਛੁਟੀ ਦੁਹੂੰ ਕੇ ਮਨ ਤੇ ਹਸਿ ਕੈ ਹਰਿ ਤੋ ਇਹ ਬਾਤ ਕਹੀ ਹੈ।","roman":"Sank chhutee duhoon ke man te hasi kai hari to ih baat kahee hai |","meaning_en":"Hesitation left the minds of both; then Hari, laughing, said this:","page":376,"meaning_status":"draft"},{"gurmukhi":"ਬਾਤ ਸੁਨੋ ਹਮਰੀ ਤੁਮ ਹੂੰ ਹਮ ਕੋ ਨਿਧਿ ਆਨੰਦ ਆਜ ਲਹੀ ਹੈ। ੨੮੦।","roman":"Baat suno hamree tum hoon ham ko nidhi aanand aaj lahee hai | 280 |","meaning_en":"'Listen to me, all of you: today I have found a treasure of joy.'","page":376,"meaning_status":"draft"}]},{"type":"verse","number":[281],"number_text":"੨੮੧।","page":377,"lines":[{"gurmukhi":"ਤਉ ਫਿਰਿ ਬਾਤ ਕਹੀ ਉਨ ਹੂੰ ਸੁਨਿ ਰੀ ਹਰਿ ਜੂ ਪਿਖਿ ਬਾਤ ਕਹੀ।","roman":"Tau phiri baat kahee un hoon suni ree hari joo pikhi baat kahee |","meaning_en":"Then they too spoke: 'Listen, friend, Hari looked at us and spoke.'","page":377,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨਿ ਜੋਰ ਹੁਲਾਸ ਬਢਿਓ ਜੀਅ ਮੈ ਗਿਨਤੀ ਸਰਤਾ ਮਗ ਨੇਹ ਬਹੀ।","roman":"Suni jor hulaas badhio jeea mai gintee sartaa mag neh bahee |","meaning_en":"Hearing this, great joy swelled in their hearts; a river of love flowed along its course beyond counting.","page":377,"meaning_status":"draft","note":"Repeats 22.97.1 with small changes."},{"gurmukhi":"ਅਬ ਸੰਕ ਛੁਟੀ ਇਨ ਕੈ ਮਨ ਕੀ ਤਬ ਹੀ ਹਸਿ ਕੈ ਇਹ ਬਾਤ ਕਹੀ।","roman":"Ab sank chhutee in kai man kee tab hee hasi kai ih baat kahee |","meaning_en":"Now hesitation left their minds, and then, laughing, they said this:","page":377,"meaning_status":"draft"},{"gurmukhi":"ਅਬ ਸਤਿ ਭਯੋ ਹਮ ਕੌ ਦੁਰਗਾ ਬਰੁ ਮਾਤ ਸਦਾ ਇਹ ਸਤਿ ਸਹੀ। ੨੮੧।","roman":"Ab sati bhayo ham kau durgaa baru maat sadaa ih sati sahee | 281 |","meaning_en":"'Now Mother Durga's boon to us has come true; it is ever true and right.'","page":377,"meaning_status":"draft"}]},{"type":"verse","number":[282],"number_text":"੨੮੨।","page":377,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਤਬੈ ਕਰ ਕੇਲ ਤਿਨੋ ਸੰਗਿ ਪੈ ਪਟ ਦੇ ਕਰਿ ਛੋਰ ਦਈ ਹੈ।","roman":"Kaanh tabai kar kel tino sangi pai pat de kari chhor daee hai |","meaning_en":"Then Kanh, having played with them, gave them their clothes and let them go.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਹੋਇ ਇਕਤ੍ਰ ਤਬੈ ਗੁਪੀਆ ਸਭ ਚੰਡਿ ਸਰਾਹਤ ਧਾਮ ਗਈ ਹੈ।","roman":"Hoi ikatr tabai gupeeaa sabh chandi saraahat dhaam gaee hai |","meaning_en":"Then all the gopis, gathering together, went home praising Chandi.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਆਨੰਦ ਅਤਿ ਸੁ ਬਢਿਯੋ ਤਿਨ ਕੇ ਜੀਅ ਸੋ ਉਪਮਾ ਕਬਿ ਚੀਨ ਲਈ ਹੈ।","roman":"Aanand ati su badhiyo tin ke jeea so upmaa kabi cheen laee hai |","meaning_en":"Great joy grew in their hearts, and the poet found this comparison for it:","page":377,"meaning_status":"draft"},{"gurmukhi":"ਜਿਉ ਅਤਿ ਮੇਘ ਪਰੈ ਧਰਿ ਪੈ ਧਰਿ ਜ੍ਯੋ ਸਬਜੀ ਸੁਭ ਰੰਗ ਭਈ ਹੈ। ੨੮੨।","roman":"Jiu ati megh parai dhari pai dhari jyo sabjee subh rang bhaee hai | 282 |","meaning_en":"as when heavy rain falls on the earth and the earth turns a lovely green.","page":377,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"The gopis said:","page":377,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arill.","page":377,"meaning_status":"draft"},{"type":"verse","number":[283],"number_text":"੨੮੩।","page":377,"lines":[{"gurmukhi":"ਧੰਨਿ ਚੰਡਿਕਾ ਮਾਤ ਹਮੈ ਬਰੁ ਇਹ ਦਯੋ।","roman":"Dhanni chandikaa maat hamai baru ih dayo |","meaning_en":"Blessed is Mother Chandika, who gave us this boon.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਧੰਨਿ ਦਿਯੋਸ ਹੈ ਆਜ ਕਾਨ੍ਹ ਹਮ ਮਿਤ ਭਯੋ।","roman":"Dhanni diyos hai aaj kaanh ham mit bhayo |","meaning_en":"Blessed is this day, that today Kanh has become our beloved.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਦੁਰਗਾ ਅਬ ਇਹ ਕਿਰਪਾ ਹਮ ਪਰ ਕੀਜੀਐ।","roman":"Durgaa ab ih kirpaa ham par keejeeai |","meaning_en":"Durga, now do us this kindness:","page":377,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਾਨਰ ਕੋ ਬਹੁ ਦਿਵਸ ਸੁ ਦੇਖਨ ਦੀਜੀਐ। ੨੮੩।","roman":"Ho kaanar ko bahu divas su dekhan deejeeai | 283 |","meaning_en":"let us see Kanh for many days.","page":377,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","roman":"Gopee baach devee joo so","meaning_en":"The gopis said to the goddess:","page":377,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":377,"meaning_status":"draft"},{"type":"verse","number":[284],"number_text":"੨੮੪।","page":377,"lines":[{"gurmukhi":"ਚੰਡਿ ਕ੍ਰਿਪਾ ਹਮ ਪੈ ਕਰੀਐ ਹਮਰੋ ਅਤਿ ਪ੍ਰੀਤਮ ਹੋਇ ਕਨਈਯਾ।","roman":"Chandi kripaa ham pai kareeai hamro ati preetam hoi kanaeeyaa |","meaning_en":"'Chandi, be kind to us: may Kanhaiya be our dearest beloved.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਪਾਇ ਪਰੇ ਹਮ ਹੂੰ ਤੁਮਰੇ ਹਮ ਕਾਨ੍ਹ ਮਿਲੈ ਮੁਸਲੀਧਰ ਭਈਯਾ।","roman":"Paai pare ham hoon tumre ham kaanh milai musleedhar bhaeeyaa |","meaning_en":"We fall at your feet: may we meet Kanh, the brother of Balram.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਯਾਹੀ ਤੇ ਦੈਤ ਸੰਘਾਰਨ ਨਾਮ ਕਿਧੋ ਤੁਮਰੋ ਸਭ ਹੀ ਜੁਗ ਗਈਯਾ।","roman":"Yaahee te dait sanghaaran naam kidho tumro sabh hee jug gaeeyaa |","meaning_en":"For this your name, Destroyer of Demons, has been sung in every age.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਤਉ ਹਮ ਪਾਇ ਪਰੀ ਤੁਮਰੇ ਜਬ ਹੀ ਤੁਮ ਤੇ ਇਹ ਪੈ ਬਰ ਪਈਯਾ। ੨੮੪।","roman":"Tau ham paai paree tumre jab hee tum te ih pai bar paeeyaa | 284 |","meaning_en":"So we fell at your feet, and then we received this boon from you.'","page":377,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":377,"meaning_status":"draft"},{"type":"verse","number":[285],"number_text":"੨੮੫।","page":377,"lines":[{"gurmukhi":"ਦੈਤਨ ਕੀ ਮ੍ਰਿਤ ਸਾਧ ਸੇਵਕ ਕੀ ਬਰਤਾ ਤੂ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਆਦਿ ਅੰਤ ਹੂੰ ਕੀ ਕਰਤਾ।","roman":"Daitan kee mrit saadh sevak kee bartaa too kahai kabi syaam aadi ant hoon kee kartaa |","meaning_en":"'You are death to the demons and the giver of boons to saints and servants; says the poet Shyam, you are the maker of beginning and end.","page":377,"meaning_status":"draft","note":"ਬਰਤਾ: read as 'giver of boons'; uncertain."},{"gurmukhi":"ਦੀਜੈ ਬਰਦਾਨ ਮੋਹਿ ਕਰਤ ਬਿਨੰਤੀ ਤੋਹਿ ਕਾਨ੍ਹ ਬਰੁ ਦੀਜੈ ਦੋਖ ਦਾਰਦ ਕੀ ਹਰਤਾ।","roman":"Deejai bardaan mohi karat binantee tohi kaanh baru deejai dokh daarad kee hartaa |","meaning_en":"Grant me a boon, I pray to you: grant me Kanh as husband, you remover of faults and poverty.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਤੂ ਹੀ ਪਾਰਬਤੀ ਅਸਟ ਭੁਜੀ ਤੁਹੀ ਦੇਵੀ ਤੁਹੀ ਤੁਹੀ ਰੂਪ ਛੁਧਾ ਤੁਹੀ ਪੇਟ ਹੂੰ ਕੀ ਭਰਤਾ।","roman":"Too hee paarabtee asat bhujee tuhee devee tuhee tuhee roop chhudhaa tuhee pet hoon kee bhartaa |","meaning_en":"You are Parbati, the eight-armed one; you are the goddess; you are the form of hunger, and you are the filler of the belly.","page":377,"meaning_status":"draft"},{"gurmukhi":"ਤੁਹੀ ਰੂਪ ਲਾਲ ਤੁਹੀ ਸੇਤ ਰੂਪ ਪੀਤ ਤੁਹੀ ਤੁਹੀ ਰੂਪ ਧਰਾ ਕੋ ਹੈ ਤੁਹੀ ਆਪ ਕਰਤਾ।੨੮੫।","roman":"Tuhee roop laal tuhee set roop peet tuhee tuhee roop dharaa ko hai tuhee aap kartaa | 285 |","meaning_en":"You are the red form, you the white, you the yellow; you are the form of the earth, and you yourself are the creator.'","page":377,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":377,"meaning_status":"draft"},{"type":"verse","number":[286],"number_text":"੨੮੬।","page":377,"lines":[{"gurmukhi":"ਬਾਹਨਿ ਸਿੰਘ ਭੁਜਾ ਅਸਟਾ ਜਿਹ ਚਕ੍ਰ ਤ੍ਰਿਸੂਲ ਗਦਾ ਕਰ ਮੈ।","roman":"Baahni singh bhujaa astaa jih chakr trisool gadaa kar mai |","meaning_en":"She whose mount is the lion, who has eight arms, with discus, trident and mace in her hands,","page":377,"meaning_status":"draft"},{"gurmukhi":"ਬਰਛੀ ਸਰ ਢਾਲ ਕਮਾਨ ਨਿਖੰਗ ਧਰੇ ਕਟਿ ਜੋ ਬਰ ਹੈ ਬਰਮੈ।","roman":"Barchhee sar dhaal kamaan nikhang dhare kati jo bar hai barmai |","meaning_en":"who wears spear, arrows, shield, bow and quiver at her waist, and is clad in fine armour:","page":377,"meaning_status":"draft","note":"ਬਰਮੈ: read as 'armour'."},{"gurmukhi":"ਗੁਪੀਆ ਸਭ ਸੇਵ ਕਰੈ ਤਿਹ ਕੀ ਚਿਤ ਦੈ ਤਿਹ ਮੈ ਹਿਤੁ ਕੈ ਹਰਿ ਮੈ।","roman":"Gupeeaa sabh sev karai tih kee chit dai tih mai hitu kai hari mai |","meaning_en":"all the gopis serve her, setting their minds on her, out of love for Hari.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਅਛਤ ਧੂਪ ਪੰਚਾਮ੍ਰਿਤ ਦੀਪ ਜਗਾਵਤ ਹਾਰ ਡਰੈ ਗਰ ਮੈ। ੨੮੬।","roman":"Puni achhat dhoop panchaamrit deep jagaavat haar darai gar mai | 286 |","meaning_en":"Then with rice, incense, panchamrit, lit lamps, they put garlands around her neck.","page":378,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":378,"meaning_status":"draft"},{"type":"verse","number":[287],"number_text":"੨੮੭।","page":378,"lines":[{"gurmukhi":"ਤੋਹੀ ਕੋ ਸੁਨੈ ਹੈ ਜਾਪ ਤੇਰੋ ਹੀ ਜਪੈ ਹੈ ਧਿਆਨ ਤੇਰੋ ਹੀ ਧਰੈ ਹੈ ਨ ਜਪੈ ਹੈ ਕਾਹੂੰ ਆਨ ਕੋ।","roman":"Tohee ko sunai hai jaap tero hee japai hai dhiaan tero hee dharai hai na japai hai kaahoon aan ko |","meaning_en":"'We will listen to you alone, repeat your name alone, meditate on you alone, and repeat the name of no other.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਤੇਰੋ ਗੁਨ ਗੈ ਹੈ ਹਮ ਤੇਰੇ ਹੀ ਕਹੈ ਹੈ ਫੂਲ ਤੋਹੀ ਪੈ ਡਰੈ ਹੈ ਸਭ ਰਾਖੈ ਤੇਰੇ ਮਾਨ ਕੋ।","roman":"Tero gun gai hai ham tere hee kahai hai phool tohee pai darai hai sabh raakhai tere maan ko |","meaning_en":"We will sing your praises and speak of you alone; we will offer flowers to you alone, and all will uphold your honour.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਜੈਸੇ ਬਰੁ ਦੀਨੋ ਹਮੈ ਹੋਇ ਕੈ ਪ੍ਰਸੰਨਿ ਪਾਛੈ ਤੈਸੇ ਬਰ ਦੀਜੈ ਹਮੈ ਕਾਨ੍ਹ ਸੁਰ ਗ੍ਯਾਨ ਕੋ।","roman":"Jaise baru deeno hamai hoi kai prasanni paachhai taise bar deejai hamai kaanh sur gyaan ko |","meaning_en":"As you were pleased and gave us a boon before, so now give us the boon of Kanh, the god of wisdom.","page":378,"meaning_status":"draft","note":"ਸੁਰ ਗ੍ਯਾਨ: sense uncertain."},{"gurmukhi":"ਦੀਜੀਐ ਬਿਭੂਤਿ ਕੈ ਬਨਾਸਪਤੀ ਦੀਜੈ ਕੈਧੋ ਮਾਲਾ ਦੀਜੈ ਮੋਤਿਨ ਕੈ ਮੁੰਦ੍ਰਾ ਦੀਜੈ ਕਾਨ੍ਹਕੋ।੨੮੭।","roman":"Deejeeai bibhooti kai banaasaptee deejai kaidho maalaa deejai motin kai mundraa deejai kaanhako | 287 |","meaning_en":"Give us ashes, or give us the plants of the forest, or a rosary of pearls, or give us earrings for Kanh's sake.'","page":378,"meaning_status":"draft","note":"Read as the gopis offering to take up the ascetic's ashes, forest life, rosary and earrings for Kanh; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਦੇਵੀ ਬਾਚ","gurmukhi":"ਦੇਵੀ ਬਾਚ","roman":"Devee baach","meaning_en":"The goddess said:","page":378,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":378,"meaning_status":"draft"},{"type":"verse","number":[288],"number_text":"੨੮੮।","page":378,"lines":[{"gurmukhi":"ਤੋ ਹਸ ਬਾਤ ਕਹੀ ਦੁਰਗਾ ਹਮ ਤੋ ਤੁਮ ਕੋ ਹਰਿ ਕੋ ਬਰੁ ਦੈ ਹੈ।","roman":"To has baat kahee durgaa ham to tum ko hari ko baru dai hai |","meaning_en":"Then Durga said, smiling, 'I will give you the boon of Hari.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਹੋਹੁ ਪ੍ਰਸੰਨਿ ਸਭੈ ਮਨ ਮੈ ਤੁਮ ਸਤ ਕਹਿਯੋ ਨਹੀ ਝੂਠ ਕਹੈ ਹੈ।","roman":"Hohu prasanni sabhai man mai tum sat kahiyo nahee jhooth kahai hai |","meaning_en":"Be glad in your hearts, all of you; I have spoken the truth and will not speak falsely.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨਹਿ ਕੋ ਸੁਖ ਹੋ ਤੁਮ ਕੋ ਹਮ ਸੋ ਸੁਖ ਸੋ ਅਖੀਆ ਭਰਿ ਲੈ ਹੈ।","roman":"Kaanhi ko sukh ho tum ko ham so sukh so akheeaa bhari lai hai |","meaning_en":"You will have joy with Kanh, and through me you will feast your eyes in happiness.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਜਾਹੁ ਕਹਿਯੋ ਸਭ ਹੀ ਤੁਮ ਡੇਰਨ ਕਾਲ੍ਹ ਵਹੈ ਬਰੁ ਕੋ ਤੁਮ ਪੈ ਹੈ। ੨੮੮।","roman":"Jaahu kahiyo sabh hee tum deran kaalh vahai baru ko tum pai hai | 288 |","meaning_en":"All of you go to your homes; tomorrow you will receive that very boon.'","page":378,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"The poet said:","page":378,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":378,"meaning_status":"draft"},{"type":"verse","number":[289],"number_text":"੨੮੯।","page":378,"lines":[{"gurmukhi":"ਹ੍ਵੈ ਪ੍ਰਸੰਨ੍ਯ ਸਭ ਬ੍ਰਿਜ ਬਧੂ ਤਿਹ ਕੋ ਸੀਸ ਨਿਵਾਇ।","roman":"Hvai prasanny sabh brij badhoo tih ko sees nivaai |","meaning_en":"All the women of Braj, pleased, bowed their heads to her,","page":378,"meaning_status":"draft"},{"gurmukhi":"ਪਰਿ ਪਾਇਨ ਕਰਿ ਬੇਨਤੀ ਚਲੀ ਗ੍ਰਿਹਨ ਕੌ ਧਾਇ। ੨੮੯।","roman":"Pari paain kari bentee chalee grihan kau dhaai | 289 |","meaning_en":"fell at her feet, made their prayer, and hurried off to their homes.","page":378,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":378,"meaning_status":"draft"},{"type":"verse","number":[290],"number_text":"੨੯੦।","page":378,"lines":[{"gurmukhi":"ਆਪਸ ਮੈ ਕਰ ਜੋਰਿ ਸਭੈ ਗੁਪੀਆ ਚਲਿ ਧਾਮ ਗਈ ਹਰਖਾਨੀ।","roman":"Aapas mai kar jori sabhai gupeeaa chali dhaam gaee harkhaanee |","meaning_en":"Holding hands with one another, all the gopis went home rejoicing.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝ ਦਯੋ ਹਮ ਕੋ ਦੁਰਗਾ ਬਰੁ ਸ੍ਯਾਮ ਚਲੀ ਕਹਤੀ ਇਹ ਬਾਨੀ।","roman":"Reejh dayo ham ko durgaa baru syaam chalee kahtee ih baanee |","meaning_en":"'Durga, pleased, has given us the boon of Shyam,' they went saying.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਆਨੰਦ ਮਤ ਭਰੀ ਮਦ ਸੋ ਸਭ ਸੁੰਦਰ ਧਾਮਨ ਕੋ ਨਿਜਕਾਨੀ।","roman":"Aanand mat bharee mad so sabh sundar dhaaman ko nijkaanee |","meaning_en":"All of them, drunk with the wine of joy, came near their lovely homes.","page":378,"meaning_status":"draft"},{"gurmukhi":"ਦਾਨ ਦਯੋ ਦਿਜਹੂੰ ਬਹੁਤਿਯੋ ਮਨ ਇਛਤ ਹੈ ਹਰਿ ਹੋ ਹਮ ਜਾਨੀ। ੨੯੦।","roman":"Daan dayo dijhoon bahutiyo man ichhat hai hari ho ham jaanee | 290 |","meaning_en":"They gave many gifts to the Brahmins, knowing they would have Hari, whom their hearts desired.","page":378,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":378,"meaning_status":"draft"},{"type":"verse","number":[291],"number_text":"੨੯੧।","page":378,"lines":[{"gurmukhi":"ਸਮੈ ਭਲੈ ਇਕ ਘਾਤ ਸਿਉ ਹ੍ਵੈ ਇਕਤ੍ਰ ਸਭ ਬਾਲ।","roman":"Samai bhalai ik ghaat siu hvai ikatr sabh baal |","meaning_en":"At a good time, at an opportune moment, all the young women gathered together,","page":378,"meaning_status":"draft"},{"gurmukhi":"ਅੰਗ ਸਭੈ ਗਿਨਨੈ ਲਗੀ ਕਰਿ ਕੈ ਬਾਤ ਰਸਾਲ। ੨੯੧।","roman":"Ang sabhai ginnai lagee kari kai baat rasaal | 291 |","meaning_en":"and began to recount all his limbs, talking sweetly.","page":378,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":379,"meaning_status":"draft"},{"type":"verse","number":[292],"number_text":"੨੯੨।","page":379,"lines":[{"gurmukhi":"ਕੋਊ ਕਹੈ ਹਰਿ ਕੋ ਮੁਖ ਸੁੰਦਰ ਕੋਊ ਕਹੈ ਸੁਭ ਨਾਕ ਬਨਿਯੋ ਹੈ।","roman":"Ko'oo kahai hari ko mukh sundar ko'oo kahai subh naak baniyo hai |","meaning_en":"One says Hari's face is beautiful; one says his nose is finely shaped.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਕੋਊ ਕਹੈ ਕਟਿ ਕੇਹਰਿ ਸੀ ਤਨ ਕੰਚਨ ਸੋ ਰਿਝਿ ਕਾਹੂ ਗਨਿਯੋ ਹੈ।","roman":"Ko'oo kahai kati kehri see tan kanchan so rijhi kaahoo ganiyo hai |","meaning_en":"One says his waist is like a lion's; another, delighted, counts his body as like gold.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਨੈਨ ਕੁਰੰਗ ਸੇ ਕੋਊ ਗਨੈ ਜਸੁ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਭਨਿਯੋ ਹੈ।","roman":"Nain kurang se ko'oo ganai jasu taa chhabi ko kabi syaam bhaniyo hai |","meaning_en":"One reckons his eyes like a deer's; the poet Shyam has told the praise of that beauty.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਲੋਗਨ ਮੈ ਜਿਮ ਜੀਵ ਬਨਿਯੋ ਤਿਨ ਕੇ ਤਨ ਮੈ ਤਿਮ ਕਾਨ੍ਹ ਮਨਿਯੋ ਹੈ। ੨੯੨।","roman":"Logan mai jim jeev baniyo tin ke tan mai tim kaanh maniyo hai | 292 |","meaning_en":"As the soul lives in people's bodies, so Kanh is held within theirs.","page":379,"meaning_status":"draft"}]},{"type":"verse","number":[293],"number_text":"੨੯੩।","page":379,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਪੇਖਿ ਕਲਾਨਿਧਿ ਸੌ ਮੁਖ ਰੀਝ ਰਹੀ ਸਭ ਹੀ ਬ੍ਰਿਜ ਬਾਰਾ।","roman":"Kaanh ko pekhi kalaanidhi sau mukh reejh rahee sabh hee brij baaraa |","meaning_en":"Seeing Kanh's face like the moon, all the girls of Braj are enchanted.","page":379,"meaning_status":"draft","note":"ਕਲਾਨਿਧਿ: the moon."},{"gurmukhi":"ਮੋਹਿ ਰਹੇ ਭਗਵਾਨ ਉਤੇ ਇਨਹੂੰ ਦੁਰਗਾ ਬਰੁ ਚੇਟਕ ਡਾਰਾ।","roman":"Mohi rahe bhagvaan ute inhoon durgaa baru chetak daaraa |","meaning_en":"There the Lord is captivated, and here these girls; the boon of Durga has cast a spell.","page":379,"meaning_status":"draft","note":"ਚੇਟਕ: 'spell, enchantment'."},{"gurmukhi":"ਕਾਨਿ ਟਿਕੈ ਗ੍ਰਿਹ ਅਉਰ ਬਿਖੈ ਤਿਹ ਕੋ ਅਤਿ ਹੀ ਜਸੁ ਸ੍ਯਾਮ ਉਚਾਰਾ।","roman":"Kaani tikai grih aur bikhai tih ko ati hee jasu syaam uchaaraa |","meaning_en":"Kanh stays in one home or another; Shyam has sung his great praise.","page":379,"meaning_status":"draft","note":"ਕਾਨਿ ਟਿਕੈ ਗ੍ਰਿਹ ਅਉਰ ਬਿਖੈ: sense uncertain."},{"gurmukhi":"ਜੀਵ ਇਕਤ੍ਰ ਰਹੈ ਤਿਨ ਕੋ ਇਮ ਟੂਟ ਗਏ ਜਿਉ ਮ੍ਰਿਨਾਲ ਕੀ ਤਾਰਾ। ੨੯੩।","roman":"Jeev ikatr rahai tin ko im toot gae jiu mrinaal kee taaraa | 293 |","meaning_en":"Their lives stay joined together, as the fibres of a lotus stalk stay joined even when it is broken.","page":379,"meaning_status":"draft","note":"ਇਮ ਟੂਟ ਗਏ: read as the fibres holding when the stalk breaks; uncertain."}]},{"type":"verse","number":[294],"number_text":"੨੯੪।","page":379,"lines":[{"gurmukhi":"ਨੇਹੁ ਲਗਿਯੋ ਇਨ ਕੋ ਹਰਿ ਸੌ ਅਰੁ ਨੇਹੁ ਲਗਿਯੋ ਹਰਿ ਕੋ ਇਨ ਨਾਰੇ।","roman":"Nehu lagiyo in ko hari sau aru nehu lagiyo hari ko in naare |","meaning_en":"They fell in love with Hari, and Hari fell in love with these women.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਚੈਨ ਪਰੈ ਦੁਹ ਕੋ ਨਹਿ ਦ੍ਵੈ ਪਲ ਨ੍ਹਾਵਨ ਜਾਵਤ ਹੋਤ ਸਵਾਰੇ।","roman":"Chain parai duh ko nahi dvai pal nhaavan jaavat hot savaare |","meaning_en":"Neither has a moment's peace; they go to bathe early in the morning.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਯਾਮ ਭਏ ਭਗਵਾਨ ਇਨੈ ਬਸਿ ਦੈਤਨ ਕੇ ਜਿਹ ਤੇ ਦਲ ਹਾਰੇ।","roman":"Syaam bhae bhagvaan inai basi daitan ke jih te dal haare |","meaning_en":"Shyam, the Lord, by whom the armies of demons were defeated, came under their sway.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਖੇਲ ਦਿਖਾਵਤ ਹੈ ਜਗ ਕੌ ਦਿਨ ਥੋਰਨ ਮੈ ਅਬ ਕੰਸ ਪਛਾਰੇ। ੨੯੪।","roman":"Khel dikhaavat hai jag kau din thoran mai ab kans pachhaare | 294 |","meaning_en":"He shows his play to the world, and within a few days now he will cast down Kans.","page":379,"meaning_status":"draft"}]},{"type":"verse","number":[295],"number_text":"੨੯੫।","page":379,"lines":[{"gurmukhi":"ਉਤ ਜਾਗਤ ਸ੍ਯਾਮ ਇਤੈ ਗੁਪੀਆ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਹਿਤ ਕੈ ਸੰਗਿ ਤਾ ਕੇ।","roman":"Ut jaagat syaam itai gupeeaa kabi syaam kahai hit kai sangi taa ke |","meaning_en":"There Shyam lies awake, and here the gopis, says the poet Shyam, out of love for him.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝ ਰਹੀ ਤਿਹ ਪੈ ਸਭ ਹੀ ਪਿਖਿ ਨੈਨਨ ਸੋ ਫੁਨਿ ਕਾਨ੍ਹਰ ਬਾਕੇ।","roman":"Reejh rahee tih pai sabh hee pikhi nainan so phuni kaanhar baake |","meaning_en":"They are all enchanted with him, seeing with their eyes the handsome Kanh.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰੇਮ ਛਕੀ ਨ ਪਰੈ ਇਨ ਕੋ ਕਲਿ ਕਾਮ ਬਢਿਯੋ ਅਤਿ ਹੀ ਤਨ ਵਾ ਕੇ।","roman":"Prem chhakee na parai in ko kali kaam badhiyo ati hee tan vaa ke |","meaning_en":"Steeped in love, they find no ease; desire has grown very great in their bodies.","page":379,"meaning_status":"draft","note":"ਵਾ ਕੇ: printed so; read as 'their'."},{"gurmukhi":"ਖੇਲਹਿ ਪ੍ਰਾਤਹਿ ਕਾਲ ਭਏ ਹਮ ਨਾਹਿ ਲਖੈ ਹਮ ਕੈ ਜਨ ਗਾ ਕੇ। ੨੯੫।","roman":"Khelhi praathi kaal bhae ham naahi lakhai ham kai jan gaa ke | 295 |","meaning_en":"'When morning comes we will play, where the cowherds will not see us.'","page":379,"meaning_status":"draft","note":"ਹਮ ਕੈ ਜਨ ਗਾ ਕੇ: read as 'the cowherd folk'; uncertain."}]},{"type":"verse","number":[296],"number_text":"੨੯੬।","page":379,"lines":[{"gurmukhi":"ਪ੍ਰਾਤ ਭਯੋ ਚੁਹਲਾਤ ਚਿਰੀ ਜਲਜਾਤ ਖਿਰੇ ਬਨ ਗਾਇ ਛਿਰਾਨੀ।","roman":"Praat bhayo chuhlaat chiree jaljaat khire ban gaai chhiraanee |","meaning_en":"Morning came; the sparrows chirped, the lotuses bloomed, and the cows were let loose into the forest.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਗੋਪ ਜਗੇ ਪਤਿ ਗੋਪ ਜਗਿਯੋ ਕਬਿ ਸ੍ਯਾਮ ਜਗੀ ਅਰੁ ਗੋਪਨਿ ਰਾਨੀ।","roman":"Gop jage pati gop jagiyo kabi syaam jagee aru gopni raanee |","meaning_en":"The cowherds woke, the chief of the cowherds woke, says the poet Shyam, and the queen of the cowherds woke.","page":379,"meaning_status":"draft","note":"Chief and queen of the cowherds: Nand and Yashoda."},{"gurmukhi":"ਜਾਗ ਉਠੇ ਤਬ ਹੀ ਕਰੁਨਾਨਿਧਿ ਜਾਗਿ ਉਠਿਯੋ ਮੁਸਲੀਧਰ ਮਾਨੀ।","roman":"Jaag uthe tab hee karunaanidhi jaagi uthiyo musleedhar maanee |","meaning_en":"Then the treasure of mercy woke, and the honoured Balram woke too.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਗੋਪ ਗਏ ਉਤ ਨ੍ਹਾਨ ਕਰੈ ਇਤ ਕਾਨ੍ਹ ਚਲੇ ਗੁਪੀਆ ਨਿਜਕਾਨੀ। ੨੯੬।","roman":"Gop gae ut nhaan karai it kaanh chale gupeeaa nijkaanee | 296 |","meaning_en":"The cowherds went there to bathe, and here Kanh went up close to the gopis.","page":379,"meaning_status":"draft","note":"ਨਿਜਕਾਨੀ: read as 'near'."}]},{"type":"verse","number":[297],"number_text":"੨੯੭।","page":379,"lines":[{"gurmukhi":"ਬਾਤ ਕਹੈ ਰਸ ਕੀ ਹਸ ਕੈ ਨਹਿ ਅਉਰ ਕਥਾ ਰਸ ਕੀ ਕੋਊ ਭਾਖੈ।","roman":"Baat kahai ras kee has kai nahi aur kathaa ras kee ko'oo bhaakhai |","meaning_en":"Laughing, they speak of love, and no one tells any tale but of love.","page":379,"meaning_status":"draft"},{"gurmukhi":"ਚੰਚਲ ਸ੍ਰੀ ਪਤਿ ਕੇ ਅਪੁਨੇ ਦ੍ਰਿਗ ਮੋਹਿ ਤਿਨੈ ਬਤੀਆ ਇਹ ਆਖੈ।","roman":"Chanchal sree pati ke apune drig mohi tinai bateeaa ih aakhai |","meaning_en":"The playful eyes of Lakshmi's lord charm them, and he speaks these words:","page":379,"meaning_status":"draft","note":"ਸ੍ਰੀ ਪਤਿ: Krishna, lord of Lakshmi."},{"gurmukhi":"ਬਾਤ ਨ ਜਾਨਤ ਹੋ ਰਸ ਕੀ ਰਸ ਜਾਨਤ ਸੋ ਨਰ ਜੋ ਰਸ ਗਾਖੈ।","roman":"Baat na jaanat ho ras kee ras jaanat so nar jo ras gaakhai |","meaning_en":"'You do not know the ways of love; he alone knows love who tastes love.","page":379,"meaning_status":"draft","note":"ਗਾਖੈ: read as 'tastes'; uncertain."},{"gurmukhi":"ਪ੍ਰੀਤਿ ਪੜੈ ਕਰਿ ਪ੍ਰੀਤਿ ਕੜੈ ਰਸ ਰੀਤਿਨ ਚੀਤ ਸੁਨੋ ਸੋਈ ਚਾਖੈ। ੨੯੭।","roman":"Preeti parai kari preeti karai ras reetin cheet suno soee chaakhai | 297 |","meaning_en":"Love is learned by loving and drawn out by loving; listen with your hearts: whoever follows love's ways tastes it.'","page":379,"meaning_status":"draft","note":"ਪੜੈ ... ਕੜੈ: sense uncertain."}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","roman":"Gopee baach kaanh so","meaning_en":"The gopis said to Kanh:","page":380,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":380,"meaning_status":"draft"},{"type":"verse","number":[298],"number_text":"੨੯੮।","page":380,"lines":[{"gurmukhi":"ਮੀਤ ਕਹੋ ਰਸ ਰੀਤਿ ਸਬੈ ਹਮ ਪ੍ਰੀਤਿ ਭਈ ਸੁਨਬੇ ਬਤੀਆ ਕੀ।","roman":"Meet kaho ras reeti sabai ham preeti bhaee sunbe bateeaa kee |","meaning_en":"'Friend, tell us all the ways of love; we have come to love hearing your talk.","page":380,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਭਈ ਤੁਹਿ ਦੇਖਨਿ ਕੀ ਤੁਮ ਪ੍ਰੀਤਿ ਭਈ ਹਮਰੀ ਛਤੀਆ ਕੀ।","roman":"Aur bhaee tuhi dekhni kee tum preeti bhaee hamree chhateeaa kee |","meaning_en":"And we have come to love seeing you; you have come to love our breasts.'","page":380,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝਿ ਲਗੀ ਕਹਨੇ ਮੁਖ ਤੇ ਹਸਿ ਸੁੰਦਰ ਬਾਤ ਇਸੀ ਗਤੀਆ ਕੀ।","roman":"Reejhi lagee kahne mukh te hasi sundar baat isee gateeaa kee |","meaning_en":"Delighted, they began to speak, laughing, lovely words in this manner.","page":380,"meaning_status":"draft"},{"gurmukhi":"ਨੇਹ ਲਗਿਯੋ ਹਰਿ ਸੋ ਭਈ ਮੋਛਨ ਹੋਤਿ ਇਤੀ ਗਤਿ ਹੈ ਸੁ ਤ੍ਰੀਆ ਕੀ। ੨੯੮।","roman":"Neh lagiyo hari so bhaee mochhan hoti itee gati hai su treeaa kee | 298 |","meaning_en":"They fell in love with Hari and were freed; such is the state of a woman.","page":380,"meaning_status":"draft","note":"ਮੋਛਨ: read as 'freed, liberated'; uncertain."}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਦਸਮ ਸਕੰਧ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸਨਾਵਤਾਰੇ ਚੀਰ ਹਰਨ","roman":"Iti sree dasam sakandh bachitr naatak granthe krisnaavtaare cheer haran","meaning_en":"Here ends the chapter of the stealing of the clothes, in the Krishna Avatar,","page":380,"meaning_status":"draft"},{"gurmukhi":"ਧਿਆਇ ਸਮਾਪਤੰ।","roman":"Dhiaai samaaptan |","meaning_en":"in the tenth book of the holy Bachitar Natak.","page":380,"meaning_status":"draft","note":"ਦਸਮ ਸਕੰਧ: the tenth skandha (book), as of the Bhagavat."}],"page":380}});
